/**
 * Terminal-readback watermark semantics (AC-011 / AC-012 / AC-013):
 *
 * - `notified` (process-local Set, one per window session) is the DELIVERY
 *   watermark: the open-time baseline ∪ rows consumed silently while no key is
 *   watched (C3) ∪ rows actually delivered after the owner gate (C1). A row in
 *   it is never delivered again by this window. A row whose owner key differs
 *   from the watched key is deliberately NOT recorded, so taking over that key
 *   later still delivers it exactly once.
 * - `readbackDelivered` (process-local Set) is the subset of `notified` that was
 *   actually delivered. It feeds ONLY the AC-012/AC-013 unread counter — it
 *   never suppresses a delivery (the `notified` check does that).
 * - `AckStore` (`_workers.acked`, project-level, persisted) is the PM's HANDLING
 *   watermark, NOT a delivery ledger: `done` rows need no ack, an unacked row is
 *   not therefore undelivered, `ack()` rewrites `ackedAt` on re-ack, and it is
 *   read only for the widget/unread split. No branch ever replays a readback
 *   because of ack state.
 */
const POLL_INTERVAL_MS = 4000; // < 5s per AC-001

function isTerminal(status: WorkerStatus): boolean {
	return status === "done" || status === "failed" || status === "needs-clarification" || status === "lost";
}

/** AC-012/AC-013 unread count: terminal queue rows whose readback this window
 * never delivered and which the PM never acked. Pure; the caller supplies the
 * already-read `acked` set so one tick reads `_workers.acked` at most once. */
function countUnreadTerminal(
	entries: readonly WorkerEntry[],
	acked: ReadonlySet<string>,
	readbackDelivered: ReadonlySet<string>,
): number {
	let n = 0;
	for (const e of entries) {
		if (!isTerminal(e.status)) continue;
		if (acked.has(e.taskKey) || readbackDelivered.has(e.taskKey)) continue;
		n += 1;
	}
	return n;
}

export type PhaseDocName = "spec.md" | "design.md" | "plan.md";

interface DocWriteTarget {
	key: string;
	doc: PhaseDocName;
}

/** The phase-doc write/edit target, when the tool path resolves to
 * {agenticdocRoot}/{key}/spec.md | design.md | plan.md — the PM phase docs that
 * mean "this window is now executing this key". Any other path (or file) is
 * not a claim signal. */
function docWriteTarget(
	toolName: string,
	args: unknown,
	projectDir: string,
	agenticdocRoot: string,
): DocWriteTarget | undefined {
	if (toolName !== "write" && toolName !== "edit") return undefined;
	const filePath = (args as { path?: unknown } | undefined)?.path;
	if (typeof filePath !== "string" || filePath === "") return undefined;
	const rel = path.relative(path.resolve(agenticdocRoot), path.resolve(projectDir, filePath));
	if (rel.startsWith("..") || path.isAbsolute(rel)) return undefined; // outside .agenticdoc
	const parts = rel.split(path.sep);
	const doc = parts.length === 2 ? parts[1] : undefined;
	if (doc !== "spec.md" && doc !== "design.md" && doc !== "plan.md") return undefined;
	const key = parts[0] ?? "";
	if (!key || key.startsWith("_") || key.startsWith(".")) return undefined;
	return { key, doc };
}

/** The key a phase-doc write/edit belongs to (see docWriteTarget). */
export function keyFromDocWrite(
	toolName: string,
	args: unknown,
	projectDir: string,
	agenticdocRoot: string,
): string | undefined {
	return docWriteTarget(toolName, args, projectDir, agenticdocRoot)?.key;
}

/** Which phase doc was written/edited (see docWriteTarget). */
export function docFromWrite(
	toolName: string,
	args: unknown,
	projectDir: string,
	agenticdocRoot: string,
): PhaseDocName | undefined {
	return docWriteTarget(toolName, args, projectDir, agenticdocRoot)?.doc;
}

export type EvidencePhase = "spec" | "design";

/** The evidence-note write target, when the tool path resolves to
 * {agenticdocRoot}/{key}/evidence/research/spec-*.md | design-*.md. Not a
 * claim signal (only phase docs are) — but the moment evidence lands is the
 * moment an already-written phase doc's claims can be re-reviewed against
 * it. */
export function evidencePhaseFromWrite(
	toolName: string,
	args: unknown,
	projectDir: string,
	agenticdocRoot: string,
): { key: string; phase: EvidencePhase } | undefined {
	if (toolName !== "write" && toolName !== "edit") return undefined;
	const filePath = (args as { path?: unknown } | undefined)?.path;
	if (typeof filePath !== "string" || filePath === "") return undefined;
	const rel = path.relative(path.resolve(agenticdocRoot), path.resolve(projectDir, filePath));
	if (rel.startsWith("..") || path.isAbsolute(rel)) return undefined; // outside .agenticdoc
	const parts = rel.split(path.sep);
	if (parts.length !== 4 || parts[1] !== "evidence" || parts[2] !== "research") return undefined;
	const note = parts[3] ?? "";
	if (!note.endsWith(".md")) return undefined;
	const phase: EvidencePhase | undefined = note.startsWith("spec-")
		? "spec"
		: note.startsWith("design-")
			? "design"
			: undefined;
	if (!phase) return undefined;
	const key = parts[0] ?? "";
	if (!key || key.startsWith("_") || key.startsWith(".")) return undefined;
	return { key, phase };
}

/** UI notice when a phase doc and its research evidence coexist — the
 * "re-review when evidence is generated" protocol, as a *notice*, not an
 * injected instruction (mw-evidence-nudge-notify): the old sendUserMessage
 * form made the model treat the automatic nudge as the user ordering an
 * immediate review pass, so the window agent started rewriting the doc with
 * no consent and no chance to veto, hijacking the turn. The framework's role
 * is to flag the moment; the user decides when (and whether) to run the
 * review. Fires once per (key, phase) per session, only when both the phase
 * doc (>= 500 bytes) and >= 1 evidence note exist: the review needs both
 * sides of the comparison. */
export function evidenceReviewNotice(
	ctx: ExtensionContext,
	key: string,
	phase: EvidencePhase,
	agenticdocRoot: string,
	notified: Set<string>,
): void {
	const dedup = `${key}:${phase}`;
	if (notified.has(dedup)) return;
	const docs = readPhaseDocs(agenticdocRoot, key);
	const docOk = phase === "spec" ? docs.spec : docs.design;
	const evidence = phase === "spec" ? docs.specEvidence : docs.designEvidence;
	if (!docOk || evidence < 1) return;
	notified.add(dedup);
	const doc = phase === "spec" ? "spec.md" : "design.md";
	ctx.ui.notify(
		`[mw] ${key}: ${phase} 阶段证据已就位（${evidence} 份 research note）——建议对照 evidence/research/ 复查 ${doc}（断言-证据对照 / 数字口径 / 内部一致性 / 可证伪性）。何时执行复查由你决定。`,
		"info",
	);
}

/** Nudge the user toward the /goal brainstorm when the project goal is not
 * yet established. Headless sessions (print/-p) skip the nudge entirely:
 * sendUserMessage starts a generation immediately, and the queued -p prompt
 * would collide with it ("Agent is already processing") before ever reaching
 * the model — `pi -p` in any project without an established goal.md would
 * hard-fail at startup. */
export function nudgeGoalUnestablished(pi: ExtensionAPI, agenticdocRoot: string, hasUI: boolean): void {
	const goal = readGoal(agenticdocRoot);
	if (hasUI && !isGoalEstablished(goal)) {
		pi.sendUserMessage(
			"[agent-team-loop] 项目总目标（.agenticdoc/goal.md）尚未确立。\n" +
				"建议先运行 /goal，与我对话共创项目总目标——它是后续每个 spec 对齐的锚点。\n" +
				"（也可直接编辑 .agenticdoc/goal.md 填好三段内容并把 status 改为 active。）",
		);
	}
}

/** Auto-takeover on phase-doc write: writing/editing {key}/spec.md, design.md,
 * or plan.md is this window saying "I am now executing key X" — claim it and
 * watch it, exactly like /pm-key switch. A live foreign claim blocks the claim
 * (watch-only) but never the watch itself. Writing design.md / plan.md also
 * runs the next-phase evidence gate (mirrors advance_phase.py): the previous
 * phase's research notes must exist, or the user is warned immediately. */
export async function autoTakeOverFromDoc(
	pi: ExtensionAPI,
	indexStore: IndexStore,
	watch: PmWatchState,
	refreshWatch: (ctx: ExtensionContext) => void,
	key: string,
	doc: PhaseDocName,
	agenticdocRoot: string,
	ctx: ExtensionContext,
): Promise<void> {
	// Next-phase evidence gate: writing design.md means the spec phase should be
	// complete (its research notes exist); writing plan.md means design should be.
	// Fires regardless of takeover idempotency — the missing evidence is the
	// message, and it stays true until the notes are written.
	const docs = readPhaseDocs(agenticdocRoot, key);
	if (doc === "spec.md" && docs.specEvidence < 1) {
		ctx.ui.notify(
			`[mw] ${key}: no evidence/research/spec-*.md found — write the research notes (or a zero-research declaration) alongside the spec; the advance-to-design gate checks them.`,
			"warning",
		);
	}
	if (doc === "design.md" && docs.specEvidence < 1) {
		ctx.ui.notify(
			`[mw] ${key}: no evidence/research/spec-*.md found — the advance-to-design gate requires >= 1 research note (a zero-research declaration counts). Write it before advancing.`,
			"warning",
		);
	}
	if (doc === "plan.md") {
		if (!docs.design) {
			ctx.ui.notify(
				`[mw] ${key}: design.md missing or under 500 bytes — required before plan (run the system-design workflow).`,
				"warning",
			);
		} else if (docs.designEvidence < 1) {
			ctx.ui.notify(
				`[mw] ${key}: no evidence/research/design-*.md found — the advance-to-plan gate requires >= 1 research note (a zero-research declaration counts). Write it before advancing.`,
				"warning",
			);
		}
	}

	const row = indexStore.findByKey(key);
	const wasWatching = watch.key === key;
	const wasClaimed = row?.claimId === windowClaimId();
	if (wasWatching && wasClaimed) return; // already ours — nothing to do

	const result = await takeOverKey(indexStore, key, false, agenticdocRoot);
	watch.key = key;
	pi.appendEntry(WATCH_ENTRY_TYPE, { key, claimed: result.ok });
	refreshWatch(ctx);
	if (result.ok) {
		ctx.ui.notify(
			`[mw] claimed key '${key}' (doc write detected) — watching it${result.created ? " (new key registered)" : ""}.`,
			"info",
		);
		if (result.audit.length > 0) ctx.ui.notify(result.audit.join("\n"), "warning");
	} else {
		ctx.ui.notify(
			`[mw] key '${key}' is claimed by another live window (${result.blockedBy}) — watching only.`,
			"warning",
		);
	}
}

/** Restore this window's watched key from the session file (survives restart
 * and resume) and re-render the bottom widget. A watch that came with a key
 * takeover re-claims the key with this process's identity — quietly, unless
 * another live window took it over in the meantime. */
export async function restoreWatch(
	pi: ExtensionAPI,
	watch: PmWatchState,
	indexStore: IndexStore,
	workerStore: WorkerStore,
	ackStore: AckStore,
	agenticdocRoot: string,
	ctx: ExtensionContext,
): Promise<void> {
	let data: { key?: string; claimed?: boolean } | undefined;
	try {
		const entries = ctx.sessionManager.getEntries();
		for (let i = entries.length - 1; i >= 0; i--) {
			const e = entries[i];
			if (e.type === "custom" && e.customType === WATCH_ENTRY_TYPE) {
				data = e.data as { key?: string; claimed?: boolean } | undefined;
				break;
			}
		}
	} catch {
		return; // session entries unavailable — nothing to restore
	}
	if (!data?.key) return;
	const key = data.key;
	watch.key = key;

	// T-16c: the restart restore path may take a key back from THIS host's
	// conductor (a `held-conductor` synthetic claim is yieldable — T-16b). That
	// handover is correct (human priority) but must not be silent: the goal is
	// that "who took the key from the conductor, and when" stays explainable.
	// Recorded on existing surfaces only — no new event name, no new entry type:
	//   * the `_index.parallel` Claim cell (and the pm-state.md mirror) flips to
	//     this window — the state surface;
	//   * `tookOverFromConductor` rides the EXISTING `agent-team-loop:watch`
	//     session entry shape, giving the durable machine-readable act record;
	//   * a transcript notice via the existing `displaySummary` channel states
	//     the holder change out loud (passive — it never spends an agent turn).
	// The timeline is deliberately NOT written here: it has a single writer (the
	// conductor, `timeline.py` D-109) and a second seq counter would corrupt it.
	// Set only in the `held-conductor` branch, so a second restart (row now this
	// window's, or stale) leaves exactly the same record count — idempotent by
	// construction.
	let tookOverFromConductor: string | undefined;
	if (data.claimed) {
		const row = indexStore.findByKey(key);
		if (row) {
			const self = windowClaimId();
			const previousClaim = row.claimId.trim();
			const holder = claimState(previousClaim, self);
			if (holder === "held-live") {
				// Another window took over while this one was closed — keep the
				// watch (display-only) and say so; do not touch the shared row.
				// Unchanged by T-16c (requirement 3): a truly live foreign claim
				// is still never taken silently.
				ctx.ui.notify(
					`[mw] key '${key}' is claimed by another window (${row.claimId}) — watching only.`,
					"warning",
				);
			} else {
				// Our previous process is gone; re-bind ownership through the
				// atomic claim — a window that raced us to this key wins and we
				// degrade to watch-only (review M2). Quiet re-claim: no demote of
				// other active rows, no status flip; only claimId/updated move.
				const outcome = await indexStore.claim(key, self, (id) => claimState(id, self) === "held-live", {
					demoteOthers: false,
					activate: false,
				});
				if (!outcome.ok) {
					ctx.ui.notify(
						`[mw] key '${key}' is claimed by another window (${outcome.blockedBy}) — watching only.`,
						"warning",
					);
				} else {
					// This path flips the index row's Claim column too, so the
					// pm-state.md mirror must be synced as well (D-108). A failed
					// mirror never reverts the claim — the index row is
					// authoritative — but the divergence must be visible.
					const sync = syncPmStateClaimId(agenticdocRoot, key, self);
					const syncWarning = claimSyncWarningText(key, sync);
					if (syncWarning !== "") ctx.ui.notify(syncWarning, "warning");
					if (holder === "held-conductor") {
						tookOverFromConductor = previousClaim;
						displaySummary(
							pi,
							`[mw] 窗口重启恢复：key '${key}' 原由本机 autopilot conductor 接管（合成 claim ${previousClaim}），` +
								`已改由本窗口接管（${self}）。人工优先，conductor 下次 tick 让位且不再抢回；` +
								"记录面：_index.parallel 的 Claim 单元 + 本 session 的 agent-team-loop:watch entry（tookOverFromConductor）。",
						);
					}
				}
			}
		}
	}

	setWatchWidget(
		ctx,
		renderWatchLines(indexStore, workerStore, ackStore, agenticdocRoot, key, watch.dispatchedTaskKeys),
	);
	// Re-stamp the entry so it lands in the (possibly new) session file.
	// T-16c: `tookOverFromConductor` (the pre-takeover synthetic claim id) is
	// added ONLY on the handover restore, so the act record is exactly one entry
	// regardless of how often the window restarts afterwards.
	pi.appendEntry(WATCH_ENTRY_TYPE, {
		key,
		claimed: data.claimed ?? false,
		...(tookOverFromConductor === undefined ? {} : { tookOverFromConductor }),
	});

	// Saved working context (pm-save): point the user at it — a notice, never
	// an injected instruction (same principle as evidenceReviewNotice: the
	// framework flags, the user decides whether the agent reads it).
	const pmStatePath = path.join(agenticdocRoot, key, "pm-state.md");
	if (fs.existsSync(pmStatePath)) {
		const updated = fs.statSync(pmStatePath).mtime.toISOString();
		ctx.ui.notify(
			`[mw] key '${key}' 有已保存的 pm-state.md（更新于 ${updated}）。如需接续上次的工作上下文，让 agent 读取 ${key}/pm-state.md 的 Notes 区。`,
			"info",
		);
	}
}

function pickWorkerRoute(taskContent: string): { cli: string; provider: string } {
	// Global default is pi/timi: review/research are routing HINTS for the
	// agent, not claude redirects (design D-005) — a claude worker requires an
	// explicit `cli` param on dispatch_worker / /worker, where missing
	// credentials fail per-task instead of silently degrading the route.
	// The reading comes from the single-source header parser (AC-005/F-6): the
	// old `/^type:\s*codex/im` full-text regex let one body line flip the
	// dispatch CLI, outside the shared `type:` matrix.
	if (readTaskType(taskContent).type === "codex") return { cli: "codex", provider: "" };
	return { cli: "pi", provider: "timi" };
}

// Optional `model:` line in task.md → passed through to the launcher as --model/-m.
function readModel(taskContent: string): string {
	const m = taskContent.match(/^model:\s*(.+)$/im);
	return m ? m[1].trim() : "";
}

// Conductor-origin marker line (D-104): `origin: conductor`. Conductor task.md
// files are rendered by autopilot/dispatch.py render_task_md; the value is the
// literal token "conductor" (line-exact, CRLF-tolerant).
const ORIGIN_LINE_RE = /^origin:[ \t]*(\S+)[ \t\r]*$/m;

/** Dispatch origin of a task.md, when it carries an `origin:` line. */
function readTaskOrigin(taskContent: string): string | undefined {
	return ORIGIN_LINE_RE.exec(taskContent)?.[1];
}

/** Is this a conductor-owned task (D-104)? Such tasks are queued by the
 * conductor alone — the TS scan must never upsert them, closing both the
 * scan/upsert race and the re-insert-as-pending path that a launcher restart
 * (or an archived row) would otherwise open. Manual/legacy tasks carry no
 * marker and behave exactly as before (AC-012 zero regression). Unreadable
 * task.md returns false so the dispatch loop hits the same read error it
 * always did. */
function isConductorTask(taskMdPath: string): boolean {
	try {
		return readTaskOrigin(fs.readFileSync(taskMdPath, "utf8")) === "conductor";
	} catch {
		return false;
	}
}

/** Why a dispatch scan refused to queue anything (AC-020/AC-021). */
export type DispatchAlarmKind =
	| "queue-rows-unparsable"
	| "queue-unreadable"
	| "dispatch-quota"
	// A candidate outside this window's scope (AC-019/T-19): the PM must be able
	// to see what it did NOT touch, aggregated per scan — visibility, not
	// prohibition (the read side stays global, AC-024). NOTICE, not a refusal:
	// nothing was refused, these keys simply belong to somebody else. Since T-22
	// the kind carries ONLY keys with no owner record at all (no index row AND no
	// `pm-state.md` machine line / worker `trace.log`): the text names the exact
	// human action (`switch_key` / `dispatch_worker(key=…)`) because a guessed
	// index row would invent Phase/ClaimId/Deps facts.
	| "out-of-scope"
	// A registered key with undispatched work, no live claim and no live run
	// (AC-011/T-19): its owner is gone and nothing will ever re-dispatch it —
	// the conductor only skips CLAIM_LIVE keys and claiming one is forbidden
	// (AUTOPILOT-HANDOFF §5 #13), so the scan repairs it claim-free. Actionable
	// NOTICE, one per key per session, never a refusal.
	| "orphaned-keys"
	// A candidate whose product already ends the run while the ledger says
	// nothing (AC-022/T-20): refused, never re-run.
	| "run-ledger-conflict"
	// A read-only run that settled without any deliverable (AC-006): the worker
	// recorded `needs-clarification` and emitted this alarm itself, with the
	// ledger root pinned to the true `.agenticdoc` (never `<key>/workers`).
	| "no-product"
	// Residual write-guard risk (AC-007/T-03): a writeless+shell worker was
	// allowed through by contract on a target that is not statically
	// determinable (`allow-unknown`) while its basename still names a deny-list
	// artifact (`pm-state.md`, `_workers*`). The guard itself cannot block;
	// observability is the only remaining defence (design DD-08).
	| "write-scope-risk"
	// A registered key whose repair evidence is STALE (T-24/C-30): the index row
	// is `idle`/`done` (or its claim is an old legacy Claim-Id) and the key's own
	// state documents have not moved in the freshness window. C-30 measured the
	// framework treating an`idle` key's months-old worker dirs as undispatched
	// work and queuing them claim-free. Such a key is NEVER repaired — repairing
	// a foreign idle key is exactly the cross-key pollution C-30 exposed — and
	// only one neutral notice is emitted (key, judged work, why not repaired).
	| "orphan-repair-skipped"
	// A write-face gate refusal consumed on the PM dispatch path (AC-003/D-008,
	// card T-W-I13): the caller saw a `DispatchOutcome` with `ok: false`, did NOT
	// count the task as queued, and turned it into a durable ledger row. It is
	// PER TASK, so unlike the scan-level refusal kinds it must never be deduped
	// per session — every refused task has to leave its own trace.
	| "write-face-refusal"
	// Consecutive model-error terminals under one owned project key (AC-006,
	// design §3.4/D7): K=2 or more worker runs of the same key ended with
	// model-unavailable evidence. PERCEPTION ONLY — this key deliberately does
	// NOT block or alter any re-dispatch decision (blocking the automatic
	// conductor loop is the separate stalled-gate idea, design D7 option B). NOT
	// a refusal: nothing was refused, the PM is being told the model layer keeps
	// failing underneath it.
	| "model-error"
	// DP-1 pre-dispatch triage produced an advisory suggestion (mw-jev-provider-
	// integration T-03, design D-005 item 3): recorded for every produced advice,
	// never a decision input. The summary rides `detail`; the PM is woken by a
	// separate `deliverPmAlert` ONLY when the suggestion disagrees with the
	// dispatched type (and `points.dp1.alert_on_disagreement !== false`).
	| "triage-suggestion"
	// DP-1 could not produce a suggestion (disabled is NOT this kind — disabled is
	// a complete bypass). Recorded only when `triage_notify_on_unavailable=true`;
	// the dispatch proceeds unchanged and the PM is never woken by it.
	| "triage-unavailable";

export interface DispatchAlarm {
	kind: DispatchAlarmKind;
	count: number;
	detail?: string;
}

/** Alarm kinds that are NOT refusals — the scan made a scope/ownership
 * observation. Their text must stay neutral (`[mw] dispatch 提示：…`); only
 * real refusal kinds may say `[mw] dispatch 已拒绝：…` (AC-011/T-19). */
export const NOTICE_DISPATCH_ALARM_KINDS: ReadonlySet<DispatchAlarmKind> = new Set([
	"out-of-scope",
	"orphaned-keys",
	"orphan-repair-skipped",
	// AC-006: a run of model-error terminals refuses nothing — it is an
	// observation about the model layer, so its text must read as `提示`.
	"model-error",
	// T-03: DP-1 triage rows refuse nothing — the advice is advisory and the
	// unavailable notice is informational, so both read as `提示`.
	"triage-suggestion",
	"triage-unavailable",
]);

/** Is this alarm a notice (neutral wording) rather than a refusal? */
export function isNoticeDispatchAlarm(kind: DispatchAlarmKind): boolean {
	return NOTICE_DISPATCH_ALARM_KINDS.has(kind);
}

/** Autopilot ledger path (shared with the Python conductor). */
const AUTO_DECISIONS_FILE = "auto-decisions.jsonl";

/** One-line human text for a refused dispatch scan (AC-020/AC-021). Notice
 * kinds carry neutral wording; the verdict prefix is added by
 * {@link formatDispatchAlarm} (AC-011/T-19). */
export function describeDispatchAlarm(alarm: DispatchAlarm): string {
	switch (alarm.kind) {
		case "queue-rows-unparsable":
			return `${alarm.count} unreadable row(s) in _workers.parallel — dispatch refused (fix the row; nothing was queued)${
				alarm.detail ? `: ${alarm.detail}` : ""
			}`;
		case "queue-unreadable":
			return `the queue looks empty while the work has already run (key ${alarm.detail ?? "?"}) — dispatch refused instead of re-running ${
				alarm.count
			} task(s)`;
		case "dispatch-quota":
			return `scan quota reached after ${alarm.count} task(s) — the rest of this scan was refused`;
		case "out-of-scope":
			return `${alarm.count} key(s) with undispatched work but no owner record, outside this window's write scope (${
				alarm.detail ?? "?"
			}) — scanned read-only, nothing written. Action required: register the key first (switch_key <key> or dispatch_worker(key=<key>)), then dispatch; its work sits in {key}/workers/<task-key>/task.md`;
		case "orphaned-keys":
			return `${alarm.count} orphaned key(s) with undispatched work, no live claim and no live run (${
				alarm.detail ?? "?"
			}) — claim-free repair dispatch applied (the conductor stays eligible); no _index.parallel claim was written`;
		case "orphan-repair-skipped":
			return `${alarm.count} key(s) with work but stale owner evidence — claim-free repair skipped, nothing written (${
				alarm.detail ?? "?"
			})`;
		case "run-ledger-conflict":
			return `${alarm.count} task(s) already have a terminal run.json while the queue has no row for them — not re-queued${
				alarm.detail ? `: ${alarm.detail}` : ""
			}`;
		case "no-product":
			return `${alarm.count} read-only run(s) settled without a product — needs-clarification, awaiting human judgement${
				alarm.detail ? `: ${alarm.detail}` : ""
			}`;
		case "write-scope-risk":
			return `${alarm.count} write-scope residual-risk row(s) (blocked=false, risk=deny-basename)${
				alarm.detail ? ` on ${alarm.detail}` : ""
			} — the guard allowed them by contract; review the audited target`;
		case "write-face-refusal":
			return `write_face gate refused ${alarm.count} task(s)${alarm.detail ? `: ${alarm.detail}` : ""} — not queued`;
		case "model-error":
			return `${alarm.count} consecutive worker run(s) ended with model-unavailable evidence${
				alarm.detail ? ` (latest: ${alarm.detail})` : ""
			} — the same key keeps settling against a failing model; check the provider route/credential or the fallback model list before the next dispatch`;
		case "triage-suggestion":
			return `${alarm.count} pre-dispatch triage suggestion(s), advisory only — the dispatch type/role/model were NOT changed${
				alarm.detail ? `: ${alarm.detail}` : ""
			}`;
		case "triage-unavailable":
			return `pre-dispatch triage produced no suggestion — dispatch proceeds unchanged${
				alarm.detail ? ` (${alarm.detail})` : ""
			}`;
	}
}

/** The full PM alert line for one alarm (AC-011/T-19): only real refusal kinds
 * carry the `已拒绝` verdict — a notice (`out-of-scope` / `orphaned-keys`) says
 * `提示` and never reads as a refusal. */
export function formatDispatchAlarm(alarm: DispatchAlarm): string {
	const verdict = isNoticeDispatchAlarm(alarm.kind) ? "提示" : "已拒绝";
	return `[mw] dispatch ${verdict}：${describeDispatchAlarm(alarm)}`;
}

/** Append one machine-readable alarm row to the autopilot ledger
 * (`.agenticdoc/_autopilot/auto-decisions.jsonl`, AC-020/AC-021). The shape
 * mirrors the Python single writer (`conductor._append_auto_decision_row`):
 * one JSON object per line, 1-based `seq`. Decision consumers filter on
 * `phase == "decide"`, so `phase: "dispatch-alarm"` is invisible to them while
 * staying visible to humans, `mw doctor` and later consumers. Best-effort by
 * design: losing the alarm must never break dispatch. */
export function recordDispatchAlarm(agenticdocRoot: string, alarm: DispatchAlarm): void {
	try {
		const ledger = path.join(agenticdocRoot, "_autopilot", AUTO_DECISIONS_FILE);
		let seq = 1;
		try {
			seq =
				fs
					.readFileSync(ledger, "utf8")
					.split("\n")
					.filter((l) => l.trim() !== "").length + 1;
		} catch {
			seq = 1;
		}
		const row = { seq, phase: "dispatch-alarm", kind: alarm.kind, count: alarm.count, detail: alarm.detail ?? "" };
		fs.mkdirSync(path.dirname(ledger), { recursive: true });
		fs.appendFileSync(ledger, `${JSON.stringify(row)}\n`, "utf8");
	} catch (err) {
		console.error(`[mw] dispatch alarm not recorded: ${err instanceof Error ? err.message : String(err)}`);
	}
}

/** Count the write-guard residual-risk audit rows in one worker trace
 * (AC-007/T-03): `[WRITE_SCOPE]` lines carrying BOTH `blocked=false` and
 * `risk=deny-basename`. The filter is deliberately the two-field pair and never
 * `rule=allow-unknown` alone (design-write-guard-landing §5.5): the unknown tier
 * is the contract, the deny-list basename is the residual risk. Best-effort — a
 * missing/unreadable trace is zero, never an error. */
export function countWriteScopeResidualRisks(taskDir: string): number {
	let raw: string;
	try {
		raw = fs.readFileSync(path.join(taskDir, "trace.log"), "utf8");
	} catch {
		return 0;
	}
	let count = 0;
	for (const line of raw.split("\n")) {
		if (!line.startsWith("[WRITE_SCOPE] ")) continue;
		if (!line.includes("blocked=false")) continue;
		if (!line.includes("risk=deny-basename")) continue;
		count += 1;
	}
	return count;
}

/** PM-side exit for the write-guard residual risk (AC-007/DD-08): the worker
 * was allowed through by contract, so the ledger row is the remaining defence.
 * Reuses the single dispatch-alarm channel and its unchanged row shape; returns
 * the number of residual-risk rows found (0 ⇒ nothing written). */
export function recordWriteScopeResidualRisks(agenticdocRoot: string, taskKey: string, taskDir: string): number {
	const count = countWriteScopeResidualRisks(taskDir);
	if (count === 0) return 0;
	recordDispatchAlarm(agenticdocRoot, { kind: "write-scope-risk", count, detail: taskKey });
	return count;
}

/** Exit-Reason prefix every model-exhausted worker writes (design §4; the
 * worker-side T-01 half of this key). */
export const MODEL_UNAVAILABLE_PREFIX = "model unavailable:";

/** Consecutive model-error terminals before the PM records one `model-error`
 * alarm (AC-006; K=2 per design §3.4/D7). */
export const MODEL_ERROR_STREAK_K = 2;

/** `run.json.model_exhausted === true` (design §4: the worker sets it on the
 * model-exhausted terminal, exit 3). Read raw rather than through the shared
 * `RunState` type because that field is added by the worker protocol (T-01) and
 * `shared/run-store.ts` is not this file's write face; a missing, unreadable or
 * malformed record is simply `false` (never throws — the poll loop calls this
 * on every terminal row). */
export function runModelExhausted(taskDir: string): boolean {
	let raw: string;
	try {
		raw = fs.readFileSync(path.join(taskDir, RUN_FILE_NAME), "utf8");
	} catch {
		return false;
	}
	try {
		const parsed: unknown = JSON.parse(raw);
		if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return false;
		return (parsed as { model_exhausted?: unknown }).model_exhausted === true;
	} catch {
		return false;
	}
}

/** Does this terminal run carry model-unavailable evidence (AC-006/design
 * §3.4)? Two independent sources, OR'd: the worker's own
 * `run.json.model_exhausted` flag and the `## Exit Reason` body starting with
 * `model unavailable:`. Reading failures degrade to `false`, never throw. */
export function isModelErrorTerminal(taskDir: string): boolean {
	if (runModelExhausted(taskDir)) return true;
	const reason = readLastProductSectionBody(taskDir, ["Exit Reason"]);
	return (reason ?? "").trimStart().startsWith(MODEL_UNAVAILABLE_PREFIX);
}

/** Bump (model-error) or clear (every other terminal) one key's consecutive
 * model-error streak. The pure half of AC-006, exported so tests can drive the
 * sequence without standing up the poll loop. */
export function bumpModelErrorStreak(streaks: Map<string, number>, key: string, modelError: boolean): number {
	if (!modelError) {
		streaks.delete(key);
		return 0;
	}
	const next = (streaks.get(key) ?? 0) + 1;
	streaks.set(key, next);
	return next;
}

/** PM-side model-error perception for one terminal worker row (AC-006, design
 * §3.4/D7). Called once per terminal transition on the poll loop's ownership
 * branch: bumps the owning key's streak, clears it on any non-model-error
 * terminal, and records ONE `model-error` alarm row through the single
 * dispatch-alarm channel once the streak reaches {@link MODEL_ERROR_STREAK_K}.
 * `detail` is the task key of the terminal that triggered the alarm. PERCEPTION
 * ONLY: the return value is never used to block or alter a re-dispatch. */
export function recordModelErrorTerminal(
	agenticdocRoot: string,
	streakKey: string,
	taskKey: string,
	taskDir: string,
	streaks: Map<string, number>,
): number {
	const count = bumpModelErrorStreak(streaks, streakKey, isModelErrorTerminal(taskDir));
	if (count < MODEL_ERROR_STREAK_K) return count;
	recordDispatchAlarm(agenticdocRoot, { kind: "model-error", count, detail: taskKey });
	return count;
}

// ── Decision correlation: settle rows (T-08 / spec §6.2, design D-013) ─────

/** `settle.outcome` vocabulary of the archive (`decide_archive._OUTCOMES`). */
export type DecisionSettleOutcome = "pending" | "ok" | "rework" | "rollback" | "inconclusive";

/** One `kind=settle` row to append — the exact argument set of
 * `decide_archive.append_settle` (dp is derived from the decision id).
 *
 * `evidenceRef` carries the run id `<task_key>@<iso>` (`run.json.run_id`): it is
 * the per-run half of the `(decision_id, outcome, run_id)` idempotency key and
 * the only place the frozen row contract can carry it (there is no `run_id`
 * field). */
export interface DecisionSettleRow {
	decisionId: string;
	dp: string;
	key: string;
	taskKey: string | null;
	outcome: DecisionSettleOutcome;
	settledBy: "pm-auto" | "human";
	evidenceRef: string | null;
	note: string | null;
}

/** Why a terminal row produced no settle row. `no-decision-header` is the
 * explicit non-association bucket demanded by spec §6.2 — PM-local decisions,
 * long-latency (dp10), composite attribution, worker-internal `tool_call`s and
 * cross-key spillover all land there and are NEVER guessed at. */
export type DecisionSettleSkipReason =
	| "no-decision-header"
	| "needs-clarification"
	| "not-terminal"
	| "inconsistent-run"
	| "duplicate-settle"
	| "rollback-without-ok"
	| "unreadable-task-md"
	| "append-failed";

export interface DecisionSettleSkip {
	decisionId: string;
	reason: DecisionSettleSkipReason;
}

/** Mapping verdict for one terminal transition (6-state table of card T-08). */
export type DecisionSettleMapping =
	| { ok: true; outcome: DecisionSettleOutcome; note?: string }
	| { ok: false; reason: DecisionSettleSkipReason };

/** The 6 terminal-state mapping (design D-013):
 *
 * | terminal | outcome |
 * | --- | --- |
 * | `done` (exit 0) | `ok` |
 * | `failed` | `rework` |
 * | `failed` + exit 3 / `model_exhausted` | `inconclusive` |
 * | `needs-clarification` | NO row (the human is the next settle subject) |
 * | `lost` | `pending` + `note=lost` |
 * | superseded (replacement landed) | `rollback` |
 *
 * `done` is `ok` without re-reading the contract sections: the worker folds the
 * contract verdict into the exit code (`evidence.delivered && gaps.ok ? 0 : 2`),
 * so a second PM-side oracle could only disagree with the run record. */
export function mapTerminalToSettle(input: {
	status: WorkerStatus;
	/** `run.json.exit`; undefined while unknown (`lost`, pre-terminal record). */
	runExit?: number;
	/** `isModelErrorTerminal(taskDir)`: exit 3 / `model unavailable:` evidence. */
	modelError: boolean;
}): DecisionSettleMapping {
	switch (input.status) {
		case "done":
			if (input.runExit !== undefined && input.runExit !== 0) {
				// Contradictory record (status says delivered, exit says otherwise): do not
				// invent an outcome; leave the decision pending and report the anomaly.
				return { ok: false, reason: "inconsistent-run" };
			}
			return { ok: true, outcome: "ok" };
		case "failed":
			// exit 3 / model_exhausted never says anything about the work: it stays out
			// of the denominator instead of counting as rework.
			return input.modelError || input.runExit === 3
				? { ok: true, outcome: "inconclusive" }
				: { ok: true, outcome: "rework" };
		case "lost":
			// Process gone, result unknown: the explicit registration row is what closes
			// the correlation loop (without it the archive reads "still running" forever).
			return { ok: true, outcome: "pending", note: "lost" };
		case "needs-clarification":
			return { ok: false, reason: "needs-clarification" };
		default:
			return { ok: false, reason: "not-terminal" };
	}
}

/** `<dp>:<trigger_id>` split on the FIRST `:` (design D-023: trigger ids may
 * contain `:`, dp ids are kebab-case registry ids). Rejects empty halves and
 * any whitespace so a free-text value can never become a decision id. */
export function splitDecisionId(decisionId: string): { dp: string; triggerId: string } | undefined {
	const at = decisionId.indexOf(":");
	if (at <= 0 || at === decisionId.length - 1) return undefined;
	if (/\s/.test(decisionId)) return undefined;
	return { dp: decisionId.slice(0, at), triggerId: decisionId.slice(at + 1) };
}

/** One settle row already in the archive (the fields the fold needs). */
export interface DecisionSettleRecord {
	decisionId: string;
	outcome: string;
	runId: string | null;
}

/** Read the settle rows of the decision archive, tolerating foreign/broken
 * lines (a half-written tail row is not this reader's error). Returns `[]` when
 * the archive does not exist yet. */
export function readDecisionSettles(archivePath: string): DecisionSettleRecord[] {
	let content: string;
	try {
		content = fs.readFileSync(archivePath, "utf8");
	} catch {
		return [];
	}
	const rows: DecisionSettleRecord[] = [];
	for (const line of content.split("\n")) {
		if (line.trim() === "") continue;
		let parsed: unknown;
		try {
			parsed = JSON.parse(line);
		} catch {
			continue;
		}
		if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) continue;
		const row = parsed as Record<string, unknown>;
		if (row.kind !== "settle") continue;
		if (typeof row.decision_id !== "string" || typeof row.outcome !== "string") continue;
		rows.push({
			decisionId: row.decision_id,
			outcome: row.outcome,
			runId: typeof row.evidence_ref === "string" && row.evidence_ref !== "" ? row.evidence_ref : null,
		});
	}
	return rows;
}

/** Decide whether one settle row may be appended (pure): idempotency on
 * `(decision_id, outcome, run_id)` (a PM restart replay writes nothing) and the
 * `rollback` ordering rule (a rollback only exists for a decision that already
 * settled `ok` — otherwise it would fabricate a reversal that never happened).
 * Multiple settles per decision ARE legal: the fold takes the LAST one, which is
 * the only way `ok → rollback` can ever be recorded (design D-013). */
export function planDecisionSettle(input: {
	decisionId: string;
	ownerKey: string;
	taskKey: string | null;
	runId: string | null;
	outcome: DecisionSettleOutcome;
	note?: string;
	prior: readonly DecisionSettleRecord[];
}): { ok: true; row: DecisionSettleRow } | { ok: false; reason: DecisionSettleSkipReason } {
	const split = splitDecisionId(input.decisionId);
	if (!split) return { ok: false, reason: "no-decision-header" };
	// Both rules are per DECISION: another decision settling `ok` on the same run
	// says nothing about this one (and must not license a rollback for it).
	const prior = input.prior.filter((row) => row.decisionId === input.decisionId);
	if (input.outcome === "rollback" && !prior.some((row) => row.outcome === "ok")) {
		return { ok: false, reason: "rollback-without-ok" };
	}
	if (prior.some((row) => row.outcome === input.outcome && row.runId === input.runId)) {
		return { ok: false, reason: "duplicate-settle" };
	}
	return {
		ok: true,
		row: {
			decisionId: input.decisionId,
			dp: split.dp,
			key: input.ownerKey,
			taskKey: input.taskKey,
			outcome: input.outcome,
			settledBy: "pm-auto",
			evidenceRef: input.runId,
			note: input.note ?? null,
		},
	};
}

/** Append implementation for one settle row (injected in tests). */
export type DecisionSettleAppender = (row: DecisionSettleRow) => { ok: true } | { ok: false; error: string };

/** In-process delegate to the archive's SINGLE writer (`decide_archive.py`):
 * no `mw decide settle` subcommand exists yet, so the interpreter imports the
 * module and `append_settle` receives the row as JSON on stdin (state is never
 * argv — the same rule `mw decide run` follows). Delegating, instead of
 * re-implementing the `prev_sha` chain, the lock and the row validation here,
 * keeps exactly one writer for `decisions.jsonl` (design §2.7 / D2-S0). */
const APPEND_SETTLE_PROGRAM = [
	"import sys, json, pathlib",
	"sys.path.insert(0, sys.argv[1])",
	"import decide_archive",
	"payload = json.loads(sys.stdin.read())",
	"decide_archive.append_settle(",
	"    pathlib.Path(payload['archive_path']),",
	"    decision_id=payload['decision_id'],",
	"    dp=payload['dp'],",
	"    key=payload['key'],",
	"    task_key=payload['task_key'],",
	"    outcome=payload['outcome'],",
	"    settled_by=payload['settled_by'],",
	"    evidence_ref=payload['evidence_ref'],",
	"    note=payload['note'],",
	")",
].join("\n");

function archiveSettleAppender(archivePath: string): DecisionSettleAppender {
	return (row) => {
		const mwPy = findMwPy();
		if (!mwPy) return { ok: false, error: "mw.py not found" };
		const payload = JSON.stringify({
			archive_path: archivePath,
			decision_id: row.decisionId,
			dp: row.dp,
			key: row.key,
			task_key: row.taskKey,
			outcome: row.outcome,
			settled_by: row.settledBy,
			evidence_ref: row.evidenceRef,
			note: row.note,
		});
		const result = spawnSync(PYTHON_EXE, ["-X", "utf8", "-c", APPEND_SETTLE_PROGRAM, path.dirname(mwPy)], {
			input: payload,
			encoding: "utf8",
			timeout: 20_000,
			windowsHide: true,
		});
		if (result.error) return { ok: false, error: result.error.message };
		if (result.status !== 0) {
			return { ok: false, error: (result.stderr ?? "").trim() || `exit ${result.status ?? "?"}` };
		}
		return { ok: true };
	};
}

/** Test seams for the settle path (production passes none). */
export interface DecisionSettleHooks {
	/** Archive path; defaults to `<agenticdocRoot>/_autopilot/decisions.jsonl`. */
	archivePath?: string;
	/** Append implementation; defaults to {@link archiveSettleAppender}. */
	append?: DecisionSettleAppender;
	/** Run-state reader; defaults to `readRunState`. */
	readRun?: (taskDir: string) => ReturnType<typeof readRunState>;
	/** Model-terminal probe; defaults to `isModelErrorTerminal`. */
	modelError?: (taskDir: string) => boolean;
}

export interface DecisionSettleResult {
	written: DecisionSettleRow[];
	skipped: DecisionSettleSkip[];
}

/** Settle the decision one terminal worker row executes (spec §6.2 / D-013).
 *
 * Called once per terminal transition from the poll loop (the `notified` set is
 * the per-task-per-session bound, exactly like `recordWriteScopeResidualRisks` /
 * `recordModelErrorTerminal` next to it). The decision id is reverse-looked up
 * from the task's own `decision:` head line; a task without one stays
 * un-associated (never guessed). A `supersedes:` task that settled `ok` also
 * records the `rollback` of the decision it replaced. Fail-soft: an unwritable
 * archive is reported in the result, never thrown into the poll loop. */
export function recordDecisionSettle(
	agenticdocRoot: string,
	ownerKey: string,
	entry: Pick<WorkerEntry, "taskKey" | "status">,
	taskDir: string,
	hooks: DecisionSettleHooks = {},
): DecisionSettleResult {
	const result: DecisionSettleResult = { written: [], skipped: [] };
	let taskContent: string;
	try {
		taskContent = fs.readFileSync(path.join(taskDir, "task.md"), "utf8");
	} catch {
		result.skipped.push({ decisionId: "", reason: "unreadable-task-md" });
		return result;
	}
	const decisionId = (readTaskHeaderScalar(taskContent, "decision") ?? "").trim();
	if (decisionId === "") {
		result.skipped.push({ decisionId: "", reason: "no-decision-header" });
		return result;
	}
	const readRun = hooks.readRun ?? readRunState;
	const run = readRun(taskDir);
	const mapping = mapTerminalToSettle({
		status: entry.status,
		runExit: run?.exit,
		modelError: (hooks.modelError ?? isModelErrorTerminal)(taskDir),
	});
	if (!mapping.ok) {
		result.skipped.push({ decisionId, reason: mapping.reason });
		return result;
	}

	const archivePath = hooks.archivePath ?? path.join(agenticdocRoot, "_autopilot", "decisions.jsonl");
	const append = hooks.append ?? archiveSettleAppender(archivePath);
	const appendOne = (
		targetDecisionId: string,
		targetTaskKey: string | null,
		runId: string | null,
		outcome: DecisionSettleOutcome,
		note?: string,
	): void => {
		const plan = planDecisionSettle({
			decisionId: targetDecisionId,
			ownerKey,
			taskKey: targetTaskKey,
			runId,
			outcome,
			note,
			// Re-read per append: the rollback leg must see the `ok` settle this same
			// call may have just written, and a restarted PM must see the whole file.
			prior: readDecisionSettles(archivePath),
		});
		if (!plan.ok) {
			result.skipped.push({ decisionId: targetDecisionId, reason: plan.reason });
			return;
		}
		const written = append(plan.row);
		if (!written.ok) {
			result.skipped.push({ decisionId: targetDecisionId, reason: "append-failed" });
			return;
		}
		result.written.push(plan.row);
	};

	appendOne(decisionId, entry.taskKey, run?.run_id ?? null, mapping.outcome, mapping.note);

	// Rollback leg (design D-013): `supersedes:` is the only way to replace a
	// finished run. Recorded only when the replacement actually landed (`ok`) — a
	// half-failed re-dispatch must not rewrite a decision that is still in force.
	const superseded = (parseSupersedes(taskContent) ?? "").trim();
	if (superseded === "" || mapping.outcome !== "ok") return result;
	const supersededDir = path.join(path.dirname(taskDir), superseded);
	let supersededContent: string;
	try {
		supersededContent = fs.readFileSync(path.join(supersededDir, "task.md"), "utf8");
	} catch {
		result.skipped.push({ decisionId: "", reason: "unreadable-task-md" });
		return result;
	}
	const supersededDecisionId = (readTaskHeaderScalar(supersededContent, "decision") ?? "").trim();
	if (supersededDecisionId === "") {
		result.skipped.push({ decisionId: "", reason: "no-decision-header" });
		return result;
	}
	// The rollback belongs to the REPLACED run: its task key and its run id (the
	// idempotency discriminator), so a re-dispatch can never dedupe against the
	// replacement's settle.
	appendOne(supersededDecisionId, superseded, readRun(supersededDir)?.run_id ?? null, "rollback");
	return result;
}

/** The one-line ledger detail for a PM-side write-face refusal (AC-003/D-008).
 * `DispatchRefusal.reason` is byte-identical to the conductor's
 * `DispatchResult.reason`, so it already carries the stable refusal `code`, the
 * `overlap-with:<task_key>` pair and the conflict `sample` when the gate could
 * prove one. The refused task key prefixes it because the alarm row has no key
 * column of its own. */
export function writeFaceRefusalDetail(taskKey: string, refusal: DispatchRefusal): string {
	return `${taskKey}: ${refusal.reason}`;
}

/** Consume one non-ok `DispatchOutcome` on the PM dispatch path (AC-003/D-008,
 * card T-W-I13): the refusal is a zero-side-effect return value, so the caller
 * must NOT count the task as queued. It is turned into a durable ledger row
 * through the single {@link recordDispatchAlarm} channel (best-effort by
 * design: a lossy audit must never break dispatch) plus a short human-visible
 * PM alert. The two are deliberately separate — the alert is not the audit. */
function reportWriteFaceRefusal(
	agenticdocRoot: string,
	taskKey: string,
	refusal: DispatchRefusal,
	onRefusal?: (text: string) => void,
): void {
	const alarm: DispatchAlarm = {
		kind: "write-face-refusal",
		count: 1,
		detail: writeFaceRefusalDetail(taskKey, refusal),
	};
	recordDispatchAlarm(agenticdocRoot, alarm);
	onRefusal?.(formatDispatchAlarm(alarm));
}

/** Single-scan dispatch quota (AC-021). A scan that wants to queue more rows
 * than this is looking at something it does not understand (IN-3 queued 252 in
 * one scan and the launcher spawned 66 workers at once). */
export const DEFAULT_DISPATCH_MAX_PER_SCAN = 3;

/** `dispatch_max_per_scan` from the project's autopilot config (D-026/AC-021).
 *
 * An explicit `DispatchScanOptions.maxPerScan` wins (tests and refreshers);
 * otherwise the project config decides. Read-only and fail-soft: a missing,
 * unreadable or out-of-range config falls back to
 * {@link DEFAULT_DISPATCH_MAX_PER_SCAN} — a broken file must never be able to
 * disable the quota (the IN-3 direction of the failure is *more* dispatching,
 * never less). */
export function readDispatchMaxPerScan(agenticdocRoot: string): number {
	try {
		const result = readConfig(path.dirname(agenticdocRoot));
		if (!result.ok) return DEFAULT_DISPATCH_MAX_PER_SCAN;
		const value = result.config.dispatch_max_per_scan;
		return Number.isInteger(value) && value >= 1 ? value : DEFAULT_DISPATCH_MAX_PER_SCAN;
	} catch {
		return DEFAULT_DISPATCH_MAX_PER_SCAN;
	}
}

/** Product evidence for {@link dispatchNewTasks}'s empty-queue guard (AC-020):
 * files the worker itself writes into its own directory. A task dir holding
 * only `task.md` has never run — that is a fresh project, not a lost queue. */
function hasProductEvidence(taskDir: string): boolean {
	for (const name of ["output.md", "report.md", "run.json", "trace.log"]) {
		if (fs.existsSync(path.join(taskDir, name))) return true;
	}
	return false;
}

/** T-24 req. 1b: the terminal product of a task run. A task dir that already
 * holds `output.md` is HISTORY, never "undispatched work" — C-30's repair queued
 * `ga-spec-review-1` / `mw-dr-glm53` / `mw-dr-keyed-probe` precisely because
 * their months-old dirs had this file (the queue then reaped them `done` in 4s).
 * Deliberately narrower than {@link hasProductEvidence}: only the worker's final
 * product counts here, not `trace.log`/`run.json` (a fresh run may have a trace
 * without an output yet). */
function hasTerminalProduct(taskDir: string): boolean {
	return fs.existsSync(path.join(taskDir, "output.md"));
}

/** Does the key's own current state (`pm-state.md` / `plan.md`) name this
 * task-key (T-24 req. 1c)? Boundary-anchored so `task-1` never matches
 * `task-12`. Read-only and best-effort: a missing/unreadable doc is no match. */
function stateDocReferencesTask(agenticdocRoot: string, key: string, taskKey: string): boolean {
	const boundary = "[^A-Za-z0-9._-]";
	const escaped = taskKey.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const re = new RegExp(`(^|${boundary})${escaped}($|${boundary})`);
	for (const doc of keyStateDocPaths(agenticdocRoot, key)) {
		let text: string;
		try {
			text = fs.readFileSync(doc, "utf8");
		} catch {
			continue;
		}
		if (re.test(text)) return true;
	}
	return false;
}

/** Outcome of the T-24 scope narrowing for one out-of-scope key. */
interface OrphanScopeVerdict {
	/** Candidates that are genuinely undispatched work (req. 1). */
	repairable: Array<{ taskKey: string; taskMdPath: string }>;
	/** Present when the key must NOT be repaired (req. 2/3); the text is the
	 * notice's `why not repairable` reason. */
	blockReason?: string;
}

/** T-24 scope narrowing for one out-of-scope key (C-30). Two gates:
 *
 *   1. work (req. 1): drop every candidate whose dir already has `output.md`;
 *      when the key publishes state documents AND its owner evidence is stale,
 *      also drop candidates its own `pm-state.md` / `plan.md` does not name (1c);
 *   2. owner evidence (req. 2): an `idle` / `done` index row with no fresh state
 *      document and no live claim is stale — the key is history, never a repair
 *      target (req. 3).
 *
 * The reference filter (1c) is applied only on the stale-evidence path: for a
 * CURRENT owner the frozen T-19/T-22 contract deliberately repairs a trace-only
 * key whose task is not yet written into its plan (a real in-flight task). See
 * the T-24 report for this deviation from the card's unconditional 1c. */
function judgeOrphanScope(
	agenticdocRoot: string,
	key: string,
	candidates: Array<{ taskKey: string; taskMdPath: string }>,
	row: IndexEntry | undefined,
): OrphanScopeVerdict {
	const live = candidates.filter(({ taskMdPath }) => !hasTerminalProduct(path.dirname(taskMdPath)));
	const evidence = ownerEvidenceCurrent(agenticdocRoot, key, row);
	if (evidence.current) return { repairable: live };
	return {
		repairable: live.filter(({ taskKey }) => stateDocReferencesTask(agenticdocRoot, key, taskKey)),
		blockReason: evidence.reason ?? "owner 证据已过期",
	};
}

export interface DispatchScanOptions {
	/** Keys already warned about in this session — a key is reported at most once. */
	warnedKeys?: Set<string>;
	/** Fires once per undocumented key whose worker tasks were skipped.
	 * MUST return whether the event was actually broadcast: false when it was
	 * intentionally suppressed (e.g. scoped to another window's key) so the
	 * once-per-session dedup does not burn the key's only slot. */
	onDocGate?: (key: string, gaps: string[]) => boolean;
	/** Scan scope (AC-019). `pm` = this window's watched key plus `_scratch`;
	 * `cli` = the whole project. Defaults to `cli` so every pre-existing caller
	 * (the `mw` command surface, tests, refreshers) keeps its global behaviour;
	 * the PM-side automatic scan passes `pm` explicitly. */
	scope?: "pm" | "cli";
	/** The window's watched key; the only non-scratch key in `scope: "pm"`. */
	watchedKey?: string;
	/** Single-scan quota override (AC-021); defaults to
	 * {@link DEFAULT_DISPATCH_MAX_PER_SCAN}. */
	maxPerScan?: number;
	/** Run-identity gate on the task's own product (AC-022, T-20). Default: no
	 * information, i.e. pre-T-20 behaviour — the queue row alone decides.
	 * `readTaskContent` is lazy so a candidate with its own run record is decided
	 * without reading task.md. */
	runVerdict?: (task: {
		taskKey: string;
		taskDir: string;
		readTaskContent: () => string;
	}) => { ok: true } | { ok: false; reason: RunIdentityRefusal; detail?: string };
	/** Alarm sink (AC-020/AC-021). Production wires it to the ledger row (and
	 * from there to the PM alert); the scan itself never invents a write path. */
	onAlarm?: (alarm: DispatchAlarm) => void;
	/** Human-visible PM alert for a per-task write-face refusal (AC-003/D-008).
	 * Deliberately separate from {@link DispatchScanOptions.onAlarm}: the refusal
	 * row is already persisted by the scan through `recordDispatchAlarm` (one per
	 * refused task, never deduped), so this callback only carries the short
	 * `formatDispatchAlarm` text to the PM. */
	onRefusal?: (text: string) => void;
	/** ORPHANED keys already alerted in this session (AC-011/T-19) — the
	 * `orphaned-keys` alarm is once per key per session, so a key that stays
	 * orphaned does not re-wake the PM on every settled turn. */
	orphanedWarned?: Set<string>;
	/** Keys already reported by the (T-22) "has work, no owner record" notice —
	 * once per key per session, mirroring `orphanedWarned`. The notice reuses the
	 * `out-of-scope` kind; the scan still writes nothing for these keys (no
	 * `_index.parallel` row, no queue row, no task-dir mutation). */
	unregisteredWarned?: Set<string>;
}

// ── Claim-free orphan repair (AC-011/T-19) ─────────────────────────────────

/** Marker/skeleton of the service-layer envelope fallback, byte-mirrored from
 * `packages/multi-workers/launcher.py` (T-14, `envelope_fallback_inject`): the
 * same marker keeps the injection idempotent, and the same `[ENVELOPE_FALLBACK]`
 * audit token makes the fallback greppable on both sides. */
export const ENVELOPE_FALLBACK_MARKER = "<!-- mw-envelope-fallback -->";
export const ENVELOPE_FALLBACK_AUDIT = "[ENVELOPE_FALLBACK]";
const ENVELOPE_FALLBACK_SECTION_BODY =
	`${ENVELOPE_FALLBACK_AUDIT} 服务层兜底注入：原 producer 未提供本段。` +
	"这是让该行可 spawn 的最小骨架，不是任务内容，也不改变任何写面判据；" +
	"请以任务卡与 PM 指令为准，并在升级 producer 后重新派发。";
const ENVELOPE_FALLBACK_EXTRA_LINES: Readonly<Record<string, string>> = {
	写入允许面: `${ENVELOPE_FALLBACK_AUDIT} 写入允许面: 服务层兜底骨架（原 producer 未声明；写面判据不变）`,
	写入禁止面: `${ENVELOPE_FALLBACK_AUDIT} 写入禁止面: 服务层兜底骨架（原 producer 未声明；写面判据不变）`,
	验收命令: `${ENVELOPE_FALLBACK_AUDIT} 验收命令: 服务层兜底骨架（原 producer 未声明）`,
	改动历史: `${ENVELOPE_FALLBACK_AUDIT} 改动历史: 服务层兜底骨架（原 producer 未声明）；trace.log 写入事件`,
	唯一证据文件: `${ENVELOPE_FALLBACK_AUDIT} 唯一证据文件: 服务层兜底骨架（原 producer 未声明）`,
	审计目标: `${ENVELOPE_FALLBACK_AUDIT} 审计目标: 服务层兜底骨架（原 producer 未声明）`,
	未覆盖面声明: `${ENVELOPE_FALLBACK_AUDIT} 未覆盖面声明: 服务层兜底骨架（原 producer 未声明）`,
};

/** Canonical-envelope skeleton for a refused card, or `null` when the card
 * cannot be made compliant without inventing facts (missing/unknown `type:`).
 *
 * AC-011e / T-14 semantics, re-implemented on the TS side so a claim-free
 * repair does not depend on the project's `envelope_fallback` config (the very
 * config an old-form project does not have): only the MISSING pieces are
 * appended — the card's own frontmatter and body are untouched — and the
 * result is re-judged before it is returned. A skeleton that still fails yields
 * `null` and the caller stays fail-closed. Existing `[ENVELOPE_FALLBACK]`
 * marker ⇒ idempotent passthrough. */
export function synthesizeEnvelopeFallback(text: string): string | null {
	if (text.includes(ENVELOPE_FALLBACK_MARKER)) return text;
	const envelope = inspectEnvelope(text);
	if (envelope.type === "" || !isKnownDispatchType(envelope.type)) return null;
	const additions: string[] = [ENVELOPE_FALLBACK_MARKER];
	for (const section of ENVELOPE_SECTIONS) {
		if (!envelope.missing.includes(section)) continue;
		additions.push("", `## ${ENVELOPE_SECTION_LABELS[section]}`, "", ENVELOPE_FALLBACK_SECTION_BODY);
	}
	for (const item of typeExtrasMissing(envelope.type, text)) {
		const line = ENVELOPE_FALLBACK_EXTRA_LINES[item];
		if (line === undefined) return null;
		additions.push("", line);
	}
	if (additions.length === 1) return null; // nothing to inject
	const injected = `${text.replace(/\n+$/, "")}\n${additions.join("\n")}\n`;
	const after = inspectEnvelope(injected);
	const extrasAfter = after.type === "" ? [] : typeExtrasMissing(after.type, injected);
	if (!after.ok || extrasAfter.length > 0) return null;
	return injected;
}

/** Outcome of one key's claim-free repair dispatch. */
export interface OrphanRepairResult {
	key: string;
	/** Task keys actually queued (claim-free: only `_workers.parallel` moved). */
	queued: string[];
	/** Tasks the run-identity gate refused (terminal / active product). */
	refused: Array<{ taskKey: string; reason: RunIdentityRefusal; detail?: string }>;
	/** Old-form cards rewritten with the service-layer skeleton. */
	synthesized: string[];
	/** Old-form cards that could not be synthesized without inventing facts. */
	unsynthesizable: string[];
}

export interface OrphanRepairOptions {
	/** Single-call quota; defaults to the project's `dispatch_max_per_scan`. */
	maxPerScan?: number;
	/** Run-identity gate (AC-022); defaults to {@link evaluateRunIdentity} with
	 * zero-backfill semantics (a candidate without a run record passes). */
	runVerdict?: DispatchScanOptions["runVerdict"];
	/** Human-visible PM alert for a per-task write-face refusal; see
	 * {@link DispatchScanOptions.onRefusal}. */
	onRefusal?: DispatchScanOptions["onRefusal"];
}

/** Default run-identity gate for the repair path: the product decides, exactly
 * as the automatic scan's wiring does (`evaluateRunIdentity`, AC-022). */
function defaultOrphanRunVerdict(
	agenticdocRoot: string,
	ownerKey: string,
): NonNullable<DispatchScanOptions["runVerdict"]> {
	return (task) =>
		evaluateRunIdentity({
			taskDir: task.taskDir,
			readTaskContent: task.readTaskContent,
			resolveTaskDir: (supersededKey) => {
				const dir = path.join(agenticdocRoot, ownerKey, "workers", supersededKey);
				return fs.existsSync(dir) ? dir : undefined;
			},
		});
}

/** Make one old-form task.md dispatchable through the service-layer skeleton,
 * appending an `[ENVELOPE_FALLBACK]` audit fact to its trace.log. `"ok"` = the
 * card already carries a complete envelope; `"synthesized"` = rewritten;
 * `"unsynthesizable"` = missing/unknown `type:`, fail-closed. */
function ensureServiceEnvelope(
	taskMdPath: string,
	key: string,
	taskKey: string,
): "ok" | "synthesized" | "unsynthesizable" {
	let text: string;
	try {
		text = fs.readFileSync(taskMdPath, "utf8");
	} catch {
		return "unsynthesizable";
	}
	const envelope = inspectEnvelope(text);
	if (envelope.ok && typeExtrasMissing(envelope.type, text).length === 0) return "ok";
	const injected = synthesizeEnvelopeFallback(text);
	if (injected === null) return "unsynthesizable";
	try {
		fs.writeFileSync(taskMdPath, injected, "utf8");
		const audit =
			`${ENVELOPE_FALLBACK_AUDIT} ${new Date().toISOString()} ${key}/${taskKey} ` +
			"kind=repair synthesized=canonical-envelope-skeleton " +
			"(claim-free orphan repair; envelope judgement only — write-face judgement unchanged)";
		fs.appendFileSync(path.join(path.dirname(taskMdPath), "trace.log"), `${audit}\n`, "utf8");
	} catch {
		return "unsynthesizable";
	}
	return "synthesized";
}

/** Dispatch already-collected repair candidates and NEVER touch
 * `_index.parallel` — the whole point of the repair path is that the key keeps
 * its claim cell (dead/free), so `conductor.py`'s
 * `if claim == state.CLAIM_LIVE: … continue` stays false and the conductor can
 * resume driving the key at any time (AC-011). */
async function dispatchOrphanCandidates(
	workerStore: WorkerStore,
	agenticdocRoot: string,
	key: string,
	candidates: Array<{ taskKey: string; taskMdPath: string }>,
	maxPerScan: number,
	runVerdict: NonNullable<DispatchScanOptions["runVerdict"]>,
	onRefusal?: DispatchScanOptions["onRefusal"],
): Promise<OrphanRepairResult> {
	const result: OrphanRepairResult = {
		key,
		queued: [],
		refused: [],
		synthesized: [],
		unsynthesizable: [],
	};
	for (const { taskKey, taskMdPath } of candidates) {
		if (result.queued.length >= maxPerScan) break;
		const taskDir = path.dirname(taskMdPath);
		const verdict = runVerdict({
			taskKey,
			taskDir,
			readTaskContent: () => fs.readFileSync(taskMdPath, "utf8"),
		});
		if (!verdict.ok) {
			result.refused.push({ taskKey, reason: verdict.reason, detail: verdict.detail });
			continue;
		}
		const envelope = ensureServiceEnvelope(taskMdPath, key, taskKey);
		if (envelope === "unsynthesizable") {
			result.unsynthesizable.push(taskKey);
			continue;
		}
		if (envelope === "synthesized") result.synthesized.push(taskKey);
		const taskContent = fs.readFileSync(taskMdPath, "utf8");
		const { cli, provider } = pickWorkerRoute(taskContent);
		const model = readModel(taskContent);
		try {
			const outcome = await dispatchTask(
				{ taskKey, status: "pending", cli, provider, model, taskPath: taskMdPath },
				workerStore,
			);
			if (outcome.ok) {
				result.queued.push(taskKey);
			} else {
				// AC-003/D-008: a refused task is never counted as queued, and the
				// refusal leaves its own durable ledger row (best-effort).
				reportWriteFaceRefusal(agenticdocRoot, taskKey, outcome, onRefusal);
			}
		} catch (err) {
			// Same fail-closed per-task isolation as the normal scan (AC-007): one
			// unusable target.yml never blocks the rest of the repair.
			console.error(
				`[mw] orphan repair refused for ${taskKey}: ${err instanceof Error ? err.message : String(err)}`,
			);
		}
	}
	return result;
}

/** Claim-free repair dispatch for one ORPHANED key (AC-011/T-19).
 *
 * Scans `{key}/workers/<task-key>/task.md`, skips already-queued and conductor-owned
 * tasks, applies the run-identity gate, synthesizes the service-layer envelope
 * for old-form cards (with an `[ENVELOPE_FALLBACK]` audit), and queues the
 * candidate through {@link dispatchTask}. It never reads-modify-writes
 * `_index.parallel`, so the conductor's eligibility predicate is untouched: the
 * repair does not "take over" the key, it only unblocks its undispatched work. */
export async function repairDispatchOrphanedKey(
	workerStore: WorkerStore,
	agenticdocRoot: string,
	key: string,
	opts: OrphanRepairOptions = {},
): Promise<OrphanRepairResult> {
	const empty: OrphanRepairResult = { key, queued: [], refused: [], synthesized: [], unsynthesizable: [] };
	const queue = workerStore.readQueue();
	const dispatched = new Set(queue.rows.map((e) => e.taskKey));
	const maxPerScan = opts.maxPerScan ?? readDispatchMaxPerScan(agenticdocRoot);
	const runVerdict = opts.runVerdict ?? defaultOrphanRunVerdict(agenticdocRoot, key);
	let taskDirs: fs.Dirent[];
	try {
		taskDirs = fs.readdirSync(path.join(agenticdocRoot, key, "workers"), { withFileTypes: true });
	} catch {
		return empty;
	}
	const candidates: Array<{ taskKey: string; taskMdPath: string }> = [];
	for (const taskDir of taskDirs) {
		if (!taskDir.isDirectory() || taskDir.name.startsWith(".")) continue;
		const taskKey = taskDir.name;
		if (dispatched.has(taskKey)) continue;
		const taskMdPath = path.join(agenticdocRoot, key, "workers", taskKey, "task.md");
		if (!fs.existsSync(taskMdPath)) continue;
		if (isConductorTask(taskMdPath)) continue;
		candidates.push({ taskKey, taskMdPath });
	}
	if (candidates.length === 0) return empty;
	return dispatchOrphanCandidates(
		workerStore,
		agenticdocRoot,
		key,
		candidates,
		maxPerScan,
		runVerdict,
		opts.onRefusal,
	);
}

/** Does `key` have a live run? `run.json` pending/running (the worker's own
 * product, AC-022) or a queue row pending/running (the ledger's cache) both
 * count — an ORPHANED key must have neither (AC-011/T-19). */
function keyHasLiveRun(rows: WorkerEntry[], key: string): boolean {
	for (const row of rows) {
		if (row.status !== "pending" && row.status !== "running") continue;
		if (workerOwnerKey(row) === key) return true;
	}
	return false;
}

export async function dispatchNewTasks(
	workerStore: WorkerStore,
	agenticdocRoot: string,
	opts: DispatchScanOptions = {},
): Promise<void> {
	// Worker tasks live under {key}/workers/<task-key>/task.md (owner = AgenticTask
	// key) or _scratch/workers/<task-key>/task.md (keyless ad-hoc). Root-level
	// task dirs are no longer dispatched - they polluted the key namespace.
	if (!fs.existsSync(agenticdocRoot)) return;
	// Read the queue once, through `readQueue()`: its rows drive the
	// already-queued set, and any unreadable row aborts the whole scan
	// (AC-020/AC-023). This is the guard IN-3 lacked — the old code built the set
	// from `readAll()`, so a row the parser silently dropped looked like a task
	// that had never run and the entire project was re-queued (252 rows within
	// one second, 2026-10-10T02:50:05Z, peak 66 concurrent workers).
	const queue = workerStore.readQueue();
	if (queue.unparsable.length > 0) {
		opts.onAlarm?.({
			kind: "queue-rows-unparsable",
			count: queue.unparsable.length,
			detail: queue.unparsable[0]?.reason,
		});
		return;
	}
	const dispatched = new Set(queue.rows.map((e) => e.taskKey));
	const scope = opts.scope ?? "cli";
	const maxPerScan = opts.maxPerScan ?? readDispatchMaxPerScan(agenticdocRoot);
	const queueIsEmpty = queue.rows.length === 0;
	let queued = 0;

	// Visibility for the "skipped, not refused" classes (T-19/T-20): keys
	// outside this window's scope, ORPHANED keys, and candidates whose product
	// already ended the run. They are aggregated per scan and go through the same
	// alarm channel (once per kind per session at the wiring), so a healthy
	// project sees at most one row per session instead of one per candidate.
	const outOfScope: string[] = [];
	// Only keys NOT already alerted this session (T-19: one `orphaned-keys`
	// alarm per key per session — a key that stays orphaned must not re-wake the
	// PM on every settled turn).
	const orphanedFresh: string[] = [];
	// T-24 (C-30): out-of-scope keys whose work was judged but whose owner
	// evidence is stale (`idle`/`done` row, no fresh state doc, no live claim).
	// They are NOT repaired; one neutral notice per key per session. `work` is
	// the RAW candidate list (what was judged), not the narrowed list, so the
	// PM can see which historical dirs triggered the judgement.
	const orphanBlocked: Array<{ key: string; work: string[]; reason: string }> = [];
	const runRefused: Array<{ taskKey: string; reason: RunIdentityRefusal; detail?: string }> = [];
	const flushScanAlarms = (): void => {
		if (outOfScope.length > 0) {
			opts.onAlarm?.({
				kind: "out-of-scope",
				count: outOfScope.length,
				detail: `${outOfScope.slice(0, 3).join(",")}${outOfScope.length > 3 ? ",…" : ""}`,
			});
		}
		if (orphanedFresh.length > 0) {
			opts.onAlarm?.({
				kind: "orphaned-keys",
				count: orphanedFresh.length,
				detail: `${orphanedFresh.slice(0, 3).join(",")}${orphanedFresh.length > 3 ? ",…" : ""}`,
			});
		}
		if (orphanBlocked.length > 0) {
			const shown = orphanBlocked
				.slice(0, 3)
				.map((b) => `${b.key}(工作=[${b.work.join(",")}]; 原因=${b.reason})`)
				.join(", ");
			opts.onAlarm?.({
				kind: "orphan-repair-skipped",
				count: orphanBlocked.length,
				detail: `${shown}${orphanBlocked.length > 3 ? ",…" : ""}`,
			});
		}
		if (runRefused.length > 0) {
			// Aggregate, bounded: the PM needs to see WHICH tasks and WHY (the
			// distinct reasons are what tells a stale ledger from a live run),
			// without one ledger row per candidate.
			const reasons = [...new Set(runRefused.map((r) => r.reason))].sort().join(",");
			const shown = runRefused
				.slice(0, 3)
				.map((r) => `${r.taskKey}:${r.reason}${r.detail ? `(${r.detail})` : ""}`)
				.join(",");
			opts.onAlarm?.({
				kind: "run-ledger-conflict",
				count: runRefused.length,
				detail: `${runRefused.length} refused (${reasons}): ${shown}${runRefused.length > 3 ? ",…" : ""}`,
			});
		}
	};

	let owners: fs.Dirent[];
	try {
		owners = fs.readdirSync(agenticdocRoot, { withFileTypes: true });
	} catch {
		return;
	}

	const indexStore = new IndexStore(agenticdocRoot);
	for (const owner of owners) {
		if (!owner.isDirectory() || owner.name.startsWith(".")) continue;
		// T-19: every owner directory is READ (the ownership scan is global and
		// read-only); the WRITE right is decided per key below. `scope: "cli"`
		// callers keep the historical whole-project behaviour.
		const inScope = scope === "cli" || owner.name === SCRATCH_WORKERS_KEY || owner.name === opts.watchedKey;
		const workersDir = path.join(agenticdocRoot, owner.name, "workers");
		let taskDirs: fs.Dirent[];
		try {
			taskDirs = fs.readdirSync(workersDir, { withFileTypes: true });
		} catch {
			continue; // owner has no workers/ dir (plain key or meta entry)
		}
		// Collect undispatched tasks FIRST (AC-010): a key with nothing new to
		// queue must not even evaluate the docs gate — fully-queued undoc keys
		// are historical, not actionable, and gate noise for them drowns real
		// blockage in multi-key projects.
		const undispatched: Array<{ taskKey: string; taskMdPath: string }> = [];
		for (const taskDir of taskDirs) {
			if (!taskDir.isDirectory() || taskDir.name.startsWith(".")) continue;
			const taskKey = taskDir.name;
			if (dispatched.has(taskKey)) continue;
			const taskMdPath = path.join(workersDir, taskKey, "task.md");
			if (!fs.existsSync(taskMdPath)) continue;
			// D-104: conductor-owned tasks (origin: conductor) never enter the TS
			// dispatch path — not queued, not upserted, and not counted as
			// undispatched work for the docs gate below. The conductor is their
			// only queue writer; its reconciliation is the sole repair path.
			if (isConductorTask(taskMdPath)) continue;
			// AC-022 (T-20): the product carries the run's own terminal state. A task
			// whose run.json already ended is never re-queued (the queue row is a
			// cache, the product is the truth) and a live run is never duplicated;
			// more work on a finished task means a NEW task_key declaring
			// `supersedes:`. Candidates without any run record keep the pre-T-20
			// behaviour (zero backfill, P-018). The task.md read is lazy, so a
			// candidate that already has a run record is decided without any read.
			if (opts.runVerdict) {
				const verdict = opts.runVerdict({
					taskKey,
					taskDir: path.join(workersDir, taskKey),
					readTaskContent: () => fs.readFileSync(taskMdPath, "utf8"),
				});
				if (!verdict.ok) {
					runRefused.push({ taskKey, reason: verdict.reason, detail: verdict.detail });
					continue;
				}
			}
			undispatched.push({ taskKey, taskMdPath });
		}
		if (!inScope) {
			// Ownership classification only (T-19/T-22) — never write an
			// out-of-scope key from the automatic scan. A live claim (conductor
			// language: `state.CLAIM_LIVE`) means somebody else owns it; a live run
			// means it is already executing. Otherwise the key is a repair candidate
			// ONLY when it carries owner evidence: an `_index.parallel` row (T-19) OR
			// the key's own owner traces (`pm-state.md` machine lines / a worker
			// `trace.log`, T-22) — the row may have been lost to index rotation or the
			// non-atomic `dispatch_worker(key=…)` create-then-register pair. A bare
			// directory holding only `task.md` files is NOT ORPHANED: there is no
			// owner fact to reconstruct a row from, so it stays an actionable,
			// once-per-key notice and the scan writes nothing.
			const row = indexStore.findByKey(owner.name);
			if (row !== undefined && conductorClaimState(row.claimId) === "live") continue; // owned elsewhere — never write
			if (row === undefined && !keyHasOwnerTraces(agenticdocRoot, owner.name)) {
				if (
					undispatched.some((t) => !hasTerminalProduct(path.dirname(t.taskMdPath))) &&
					opts.watchedKey !== undefined &&
					!(opts.unregisteredWarned?.has(owner.name) ?? false)
				) {
					opts.unregisteredWarned?.add(owner.name);
					outOfScope.push(owner.name);
				}
				continue;
			}
			if (keyHasLiveRun(queue.rows, owner.name)) continue; // running — not orphaned
			if (undispatched.length === 0) continue; // nothing to repair
			// T-24 (C-30): narrow the work (drop dirs with a terminal `output.md`;
			// for a stale owner, require the key's own state to name the task) and
			// require the owner evidence to still be current. A key whose only
			// evidence is an `idle`/`done` row with stale state docs is history:
			// never repaired, one neutral notice (req. 2/3). The reference filter
			// is part of the block path only — see the T-24 report.
			const scopeVerdict = judgeOrphanScope(agenticdocRoot, owner.name, undispatched, row);
			if (scopeVerdict.blockReason !== undefined) {
				if (!(opts.orphanedWarned?.has(owner.name) ?? false)) {
					opts.orphanedWarned?.add(owner.name);
					orphanBlocked.push({
						key: owner.name,
						work: undispatched.map((t) => t.taskKey),
						reason: scopeVerdict.blockReason,
					});
				}
				continue;
			}
			if (scopeVerdict.repairable.length === 0) continue; // only history left
			if (queued >= maxPerScan) {
				flushScanAlarms();
				opts.onAlarm?.({ kind: "dispatch-quota", count: queued });
				return;
			}
			const repair = await dispatchOrphanCandidates(
				workerStore,
				agenticdocRoot,
				owner.name,
				scopeVerdict.repairable,
				maxPerScan - queued,
				opts.runVerdict ?? defaultOrphanRunVerdict(agenticdocRoot, owner.name),
				opts.onRefusal,
			);
			queued += repair.queued.length;
			if (!(opts.orphanedWarned?.has(owner.name) ?? false)) {
				opts.orphanedWarned?.add(owner.name);
				orphanedFresh.push(owner.name);
			}
			continue;
		}
		if (undispatched.length === 0) continue;
		// AC-020: an empty queue plus product evidence in the very tasks we are
		// about to queue is the IN-3 shape — the queue lost its rows while the
		// work had already run. Refuse the whole scan instead of re-running
		// history; a real fresh project has no such evidence and dispatches.
		if (queueIsEmpty && undispatched.some((t) => hasProductEvidence(path.dirname(t.taskMdPath)))) {
			flushScanAlarms();
			opts.onAlarm?.({ kind: "queue-unreadable", count: undispatched.length, detail: owner.name });
			return;
		}
		// Docs gate, phase-tiered (mw-worker-visibility-gate D-110): the tier comes
		// from the SCAN KEY's own phase (its pm-state '- Phase:' line), never from
		// this window's watch — the background scan and the dispatch_worker tool
		// entry must not diverge. _scratch is the ad-hoc escape hatch. Report
		// each blocked key at most once.
		if (owner.name !== SCRATCH_WORKERS_KEY) {
			const ownerPhase = new StateManager(agenticdocRoot, owner.name).read().phase ?? "";
			const gaps = dispatchDocGaps(agenticdocRoot, owner.name, ownerPhase);
			if (gaps.length > 0) {
				if (!opts.warnedKeys?.has(owner.name)) {
					// Mark as warned only when the notifier actually broadcast —
					// a suppressed broadcast (scoped to another window's key) must
					// not burn this key's once-per-session slot (review m1).
					if (opts.onDocGate?.(owner.name, gaps) !== false) {
						opts.warnedKeys?.add(owner.name);
					}
				}
				continue;
			}
		}
		for (const { taskKey, taskMdPath } of undispatched) {
			// AC-021: one scan may queue at most `maxPerScan` rows. Exceeding the
			// quota means the scan is looking at something it does not understand,
			// not that hundreds of tasks need running.
			if (queued >= maxPerScan) {
				flushScanAlarms();
				opts.onAlarm?.({ kind: "dispatch-quota", count: queued });
				return;
			}
			const taskContent = fs.readFileSync(taskMdPath, "utf8");
			const { cli, provider } = pickWorkerRoute(taskContent);
			const model = readModel(taskContent);
			try {
				const outcome = await dispatchTask(
					{
						taskKey,
						status: "pending",
						cli,
						provider,
						model,
						taskPath: taskMdPath,
					},
					workerStore,
				);
				if (outcome.ok) {
					queued += 1;
				} else {
					// AC-003/D-008: a write-face refusal is a return value, not a
					// throw — counting it as queued would both falsify the quota and
					// leave the refusal without any durable trace.
					reportWriteFaceRefusal(agenticdocRoot, taskKey, outcome, opts.onRefusal);
				}
			} catch (err) {
				// Fail-closed (mw-dual-workspace AC-007): an unusable target.yml
				// must never silently degrade to an un-injected task.md — the task
				// stays undispatched and is retried on the next scan once the
				// config is fixed. Per-task isolation: one bad task never blocks
				// the rest of the scan.
				console.error(`[mw] dispatch refused for ${taskKey}: ${err instanceof Error ? err.message : String(err)}`);
			}
		}
	}
	flushScanAlarms();
}

/** Continuation directive appended to terminal worker results: the finish
 * call wakes an idle PM (triggerTurn) — this line tells it what "continue the
 * PM loop" means per terminal status, so results are processed and the next
 * task is dispatched without the user re-prompting. Timeout failures get an
 * explicit retry policy (AC-004/D-005): the Exit Reason in the readback body
 * distinguishes idle (true hang) from wall (healthy but out of budget). */
const PM_CONTINUE_HINT =
	"[mw] worker 终态回读。请继续 PM 循环：吸收上述结果（done→推进下一任务/phase；failed→读 worker.log 与 trace.log 排查后决定重试或修复；needs-clarification→整理问题向用户澄清；超时失败（Exit Reason 含 idle/wall timeout）→ wall 型用双倍 timeout 预算重派一次，再失败转 PM 直执，idle 型直接排查环境），然后派发下一个任务或汇报阶段完成。吸收终态结果后调用 ack_worker_result(task_key)（或 /mw ack all）确认处理完成，widget 待处理区才会清空。";

/** Runtime stats for terminal worker summaries (AC-013):
 * ` (6m-style coarse duration, ph i/n)`. Preference order: exact [START]→[END]
 * interval from trace.log (present on every new-bundle terminal task), ≥2
 * [HEARTBEAT] lines (older format), then the queue row's dispatchedAt→updatedAt
 * (coarse but always present). Empty when nothing is derivable. */
function heartbeatStatsSuffix(taskDir: string, entry: WorkerEntry): string {
	const prog = readTaskProgress(taskDir);
	if (prog?.startTs && prog.endTs) {
		const durMs = Math.max(0, Date.parse(prog.endTs) - Date.parse(prog.startTs));
		const ph = prog.endPhases && prog.endPhases !== "-" ? `, ph ${prog.endPhases}` : "";
		return ` (${formatHeartbeatAge(durMs)}${ph})`;
	}
	const hb = prog?.heartbeat;
	if (hb && hb.count >= 2) {
		const durMs = Math.max(0, Date.parse(hb.lastTs) - Date.parse(hb.firstTs));
		const ph = hb.phase === "-" ? "" : `, ph ${hb.phase}/${hb.phaseTotal}`;
		return ` (${formatHeartbeatAge(durMs)}${ph})`;
	}
	const durMs = Date.parse(entry.updatedAt) - Date.parse(entry.dispatchedAt);
	if (!Number.isNaN(durMs) && durMs > 0) return ` (${formatHeartbeatAge(durMs)})`;
	return "";
}

/** Session entry type recording a delivered gate reminder. Read back on
 * restart/resume so the same ledger row is never pushed twice (design D-010).
 * Same mechanism as WATCH_ENTRY_TYPE / AUTOPILOT_SEEN_ENTRY_TYPE. */
export const GATE_REMINDER_ENTRY_TYPE = "agent-team-loop:gate-reminder-seen";

/** Session entry type recording a DROPPED gate reminder (mw-autopilot-gate-
 * alarm-liveness AC-010): "no watch", "other key" and "read error" drops must
 * leave a visible record, never vanish silently. Deliberately a SEPARATE type
 * and WITHOUT `seq`: the delivery resume path reads `e.data?.seq` from
 * {@link GATE_REMINDER_ENTRY_TYPE} entries to advance `reminderWatermark`, so a
 * drop record carrying a `seq` would suppress the real delivery that follows
 * it (DRQ-2 C5 counter-example). */
export const GATE_REMINDER_DROPPED_ENTRY_TYPE = "agent-team-loop:gate-reminder-dropped";

/** Record one dropped reminder into the session (visible via the transcript /
 * session file). Deduplicated per `${gateId}:${n}:${reason}` for this process:
 * the poll loop runs every 4 s, so an undeduped drop would append an entry per
 * tick forever. `reason` is one of the three literal drop causes. */
export function recordDroppedGateReminder(
	pi: ExtensionAPI,
	seen: Set<string>,
	reminder: { gateId: string; reminderN: number; gateKey: string },
	reason: "no-watch" | "other-key" | "read-error",
	error?: string,
): void {
	const dedup = `${reminder.gateId}:${reminder.reminderN}:${reason}`;
	if (seen.has(dedup)) return;
	seen.add(dedup);
	pi.appendEntry(GATE_REMINDER_DROPPED_ENTRY_TYPE, {
		gateId: reminder.gateId,
		n: reminder.reminderN,
		gateKey: reminder.gateKey,
		reason,
		...(error === undefined ? {} : { error }),
	});
}

// ── dp2 checkpoint narrowing (mw-decision-substitution T-07; design D-011) ──
//
// The divergence escalation below wakes the PM (triggerTurn) at the first
// mid/high convergence checkpoint of a running worker. dp2 lets a service
// answer substitute for that wake — but ONLY with the one action that is
// reversible, machine-decidable, local and free: narrowing the remaining scope
// (D-011). `split` (kill + re-dispatch, a new task-ledger entry) and
// `direct-exec` (PM takes over, bypassing the worker's process/write-face
// isolation) change the goal or widen the authorization surface, so they stay
// human decisions and take the UNCHANGED escalation path.
//
// Three closed states must stay behaviourally identical to pre-dp2 (design
// D-007 / AC-015):
//   - `.mw/decide.json` missing or `enabled != true` → complete bypass: no
//     spawn, no write (the only I/O is that one config probe);
//   - `.mw/decide-points.json` row `enabled=false` / unusable row → same bypass
//     for dp2 only (the table is the single authority, machines never write it);
//   - `mode=suggest` → Python still records the answer, but this hook NEVER acts
//     on it; the alert still wakes the PM (AC-015).
//
// Every degraded answer (unavailable / missing `checkpoint_action` / an unknown
// value) is fail-closed onto the original alert. There is no default action.

/** Decision-point id (registry authority: packages/multi-workers/decision_points.py). */
export const DP2_CHECKPOINT_ID = "dp2-checkpoint-split";

/** Registry question id whose value carries the dp2 answer. */
export const DP2_CHECKPOINT_QUESTION = "checkpoint_action";

/** Steer request file the PM writes into the worker's task dir. The worker
 * consumes it at its next checkpoint tick (design §5.3: file transport keeps
 * coordination file-driven and the PM the single writer). */
export const DP2_STEER_FILE = "steer-dp2.md";

/** Attribution marker of the narrowed-scope steer (the worker injects it as a
 * followUp; kept here so the request file and its consumer cannot drift). */
export const DP2_NARROW_MARKER = "[mw dp2-narrow]";

/** Machine header line of the request file (first line of `steer-dp2.md`).
 * Exported so the worker-side consumer strips exactly what this side wrote. */
export const DP2_STEER_REQUEST_HEADER = "[dp2-narrow-request]";

/** Appended to the PM alert when dp2 answered `narrow` but the worker can no
 * longer act on a steer (T-07b fallback, DS-4: never fail open). */
export const DP2_NARROW_FALLBACK_LINE = "[dp2-narrow-fallback] task not running; escalated instead";

/** dp2 question set in the canonical form Python hashes: `json.dumps(list(
 * questions), ensure_ascii=False, sort_keys=True, separators=(",", ":"))`
 * (decision_points.py::_questions_version). */
const DP2_QUESTIONS_CANONICAL =
	'[{"choices":["narrow","split","direct-exec","escalate"],"id":"checkpoint_action","type":"choice"}]';

/** `questions_version` for dp2 = `q-<sha256(canonical questions)[:8]>`, i.e. the
 * exact short code the Python registry derives (D-026). The suite re-derives it
 * from the registry source so a question-set edit cannot drift silently. */
export const DP2_QUESTIONS_VERSION = `q-${createHash("sha256")
	.update(DP2_QUESTIONS_CANONICAL, "utf8")
	.digest("hex")
	.slice(0, 8)}`;

/** One `[CHECKPOINT]` line reduced to the trend counters. The design's dp2
 * input asks for "最近 ≤3 条 (elapsed_s, reads, writes)" — enough to tell "still
 * climbing" from "stalled" without shipping any L2 material. */
export interface Dp2CheckpointPoint {
	elapsedMin: number;
	reads: number;
	writes: number;
}

/** Line prefix of the convergence checkpoint (format: worker/output-writer.ts
 * `appendCheckpoint`, parsed in full by shared/heartbeat.ts CHECKPOINT_LINE_RE).
 * Re-scanned here only because {@link readTaskProgress} keeps the LAST line,
 * while dp2 needs the series plus the checkpoint sequence (`#ckpt<N>`). */
const DP2_CHECKPOINT_LINE_RE =
	/^\[CHECKPOINT\] \S+ elapsed=(\d+)s reads=(\d+) writes=(\d+) phases=\S+ uniq_targets=\d+ repeat_top=\d+ risk=(?:low|mid|high)/;

/** Checkpoint series of one task dir: `total` is the number of `[CHECKPOINT]`
 * lines (the `#ckpt<N>` sequence number), `points` the last `limit` of them in
 * file order. Empty/zero when trace.log is unreadable. */
export function readCheckpointTrend(taskDir: string, limit = 3): { total: number; points: Dp2CheckpointPoint[] } {
	let content: string;
	try {
		content = fs.readFileSync(path.join(taskDir, "trace.log"), "utf8");
	} catch {
		return { total: 0, points: [] };
	}
	const all: Dp2CheckpointPoint[] = [];
	for (const line of content.split("\n")) {
		const match = DP2_CHECKPOINT_LINE_RE.exec(line);
		if (!match) continue;
		all.push({
			elapsedMin: Math.round(Number(match[1]) / 60),
			reads: Number(match[2]),
			writes: Number(match[3]),
		});
	}
	return { total: all.length, points: all.slice(-limit) };
}

/** Effective dp2 authorization PRE-READ from `.mw/decide-points.json`.
 *
 * NON-AUTHORITATIVE (design D-036「唯配置论」): the table has exactly one
 * authority, `decision_points.decide_for`. This read exists ONLY so the PM does
 * not pay for a `mw decide run` child that Python would reject — zero-spawn
 * short-circuit, nothing else. `mode`, `acted` and `decision_id` come from the
 * child payload, never from here, and when this pre-read and Python disagree
 * PYTHON WINS. Read-only (AC-010: machines never write the table).
 *
 * `source`: `default` = no table / no row (registry default for a P2 point),
 * `config` = a usable row, `invalid` = the row is present but its L2/L3/L5
 * parse degrades it (Python `force_off`). */
export interface Dp2Authorization {
	enabled: boolean;
	source: "default" | "config" | "invalid";
}

/** Mirror of the `force_off` half of `decision_points.py::_parse_row`
 * (decision_points.py:884-968): a row that is not an object (L2) — handled by
 * the caller — or whose `mode`/`note`/`tier` is not a string of the accepted
 * shape, or whose `enabled` is not a boolean (L3/L5), is `enabled=false` for
 * that dp only.
 *
 * Deliberately NOT force-off: L4 (tier value outside P0|P1|P2) and L7 (tier
 * differs from the registry) are advisory — the registry tier wins and the row
 * stays enabled, exactly like `_parse_row`. If Python's rules change, THIS is
 * the one function to fix: Python is authoritative. */
function dp2RowForceOff(row: Record<string, unknown>): boolean {
	if ("mode" in row && row.mode !== "auto" && row.mode !== "suggest") return true;
	if ("note" in row && typeof row.note !== "string") return true;
	if ("tier" in row && typeof row.tier !== "string") return true;
	return "enabled" in row && typeof row.enabled !== "boolean";
}

export function readDp2Authorization(projectDir: string): Dp2Authorization {
	const fallback: Dp2Authorization = { enabled: true, source: "default" };
	let raw: unknown;
	try {
		raw = JSON.parse(fs.readFileSync(path.join(projectDir, ".mw", "decide-points.json"), "utf8"));
	} catch {
		return fallback;
	}
	// L1 (unparsable file, or no `points` object): every dp keeps the registry
	// default, so dp2 (P2) stays enabled.
	const points = recordOf(recordOf(raw)?.points);
	if (points === undefined || !Object.hasOwn(points, DP2_CHECKPOINT_ID)) return fallback;
	// L2: a present-but-non-object row forces dp2 OFF — Python never falls back
	// to the registry default for a row it could not parse as an object.
	const row = recordOf(points[DP2_CHECKPOINT_ID]);
	if (row === undefined) return { enabled: false, source: "invalid" };
	if (dp2RowForceOff(row)) return { enabled: false, source: "invalid" };
	// A usable row: `enabled` defaults to the registry default (P2 → true).
	return { enabled: row.enabled !== false, source: "config" };
}

function recordOf(value: unknown): Record<string, unknown> | undefined {
	return value !== null && typeof value === "object" && !Array.isArray(value)
		? (value as Record<string, unknown>)
		: undefined;
}

/** Code-point-safe UTF-8 clamp, mirroring the Python field budgets. */
function clampUtf8(text: string, maxBytes: number): string {
	if (Buffer.byteLength(text, "utf8") <= maxBytes) return text;
	let out = "";
	let used = 0;
	for (const char of text) {
		const size = Buffer.byteLength(char, "utf8");
		if (used + size > maxBytes) break;
		out += char;
		used += size;
	}
	return out;
}

/** One `context.artifact_status` entry (W6 / D-052..D-054). */
export interface Dp2ArtifactStatus {
	path: string;
	exists: boolean;
	bytes: number;
}

/** Machine fields of the checkpoint, 8 + 4 (design Q5): elapsed/reads/writes/
 * phases/uniq_targets/repeat_top/risk from the line plus the writeless landing
 * suffix (land/last_land/artifact/done). Reads ride in the trend only — the
 * frozen state table has no `progress.reads`. */
export interface Dp2CheckpointStateInput {
	ownerKey: string;
	taskKey: string;
	phase: string;
	taskType: string;
	budgetMin: number;
	checkpoint: CheckpointInfo;
	trend: Dp2CheckpointPoint[];
	/** `context.artifact_status` rows (already fs-stated, ≤24 enforced here). */
	artifacts?: readonly Dp2ArtifactStatus[];
}

/** Build the dp2 structured state (spec §5.4 / D-019: L0/L1 only, ≤2000B).
 * Required fields come from `decision_points.REQUIRED_STATE_FIELDS["dp2-…"]`:
 * universal 9 + `progress.elapsed_minutes/budget_minutes/phases_done/
 * phases_total/artifact_present`; the remaining counters and the trend are
 * optional L1. */
export function buildDp2CheckpointState(input: Dp2CheckpointStateInput): Record<string, unknown> {
	const phases = splitPhaseProgress(input.checkpoint.phases);
	const progress: Record<string, unknown> = {
		elapsed_minutes: Math.max(0, Math.round(input.checkpoint.elapsedS / 60)),
		budget_minutes: Math.max(1, Math.round(input.budgetMin)),
		phases_done: phases.done,
		phases_total: phases.total,
		// Writeless roles carry the landing suffix; a write role proves its artifact
		// by having written at all (old lines have no `artifact=` field).
		artifact_present: input.checkpoint.artifactPresent ?? input.checkpoint.writes > 0,
		writes: input.checkpoint.writes,
		uniq_targets: input.checkpoint.uniqTargets,
		repeat_top: input.checkpoint.repeatTop,
		trend: input.trend.map((point) => ({
			elapsed_minutes: point.elapsedMin,
			reads: point.reads,
			writes: point.writes,
		})),
	};
	if (input.checkpoint.lastLandingS !== undefined) {
		progress.last_land_age_min = Math.round(input.checkpoint.lastLandingS / 60);
	}
	const contextSlots = DECIDE_REGISTRY[DP2_CHECKPOINT_ID]?.contextSlots ?? [];
	const context: Record<string, unknown> = {};
	if (contextSlots.includes("change_summary")) {
		// The summary is prose the model reads, not a decision field: one line,
		// capped at the slot's 600 chars, derived only from machine fields.
		const lastLand =
			typeof progress.last_land_age_min === "number" ? ` last_land_age=${progress.last_land_age_min}m` : "";
		context.change_summary = clampUtf8(
			`checkpoint elapsed=${progress.elapsed_minutes}m/${progress.budget_minutes}m ` +
				`phases=${progress.phases_done}/${progress.phases_total} writes=${progress.writes} ` +
				`artifact_present=${progress.artifact_present}${lastLand}`,
			600,
		);
	}
	if (contextSlots.includes("artifact_status") && (input.artifacts?.length ?? 0) > 0) {
		context.artifact_status = (input.artifacts ?? []).slice(0, 24).map((entry) => ({
			path: clampUtf8(entry.path, 200),
			exists: entry.exists === true,
			bytes: Math.max(0, Math.round(entry.bytes)),
		}));
	}
	const state: Record<string, unknown> = {
		// T-08 (requirement 0 / T-04b residual 1): the registry state builder and
		// `triage-client.ts::validateStructuredState` are pinned to
		// `schema_version: 2`; the dp2 checkpoint state must carry the same version
		// or the future structured-input validator would reject dp2's own input.
		schema_version: 2,
		decision_point: DP2_CHECKPOINT_ID,
		key: clampUtf8(input.ownerKey, 48),
		phase: clampUtf8(input.phase, 16),
		task_type: input.taskType,
		risk: input.checkpoint.risk,
		risk_source: "machine",
		authority_tier: "P2",
		questions_version: DECIDE_REGISTRY[DP2_CHECKPOINT_ID]?.questionsVersion ?? DP2_QUESTIONS_VERSION,
		progress,
	};
	if (Object.keys(context).length > 0) state.context = context;
	// W6: fail loud at the producer when the registry and this builder drift
	// (`task_key` used to ride here; it is not a dp2 field, so it is gone).
	assertStateMatchesRegistry(DP2_CHECKPOINT_ID, state);
	return state;
}

/** `context.artifact_status` (W6): expected task outputs first, then whatever
 * else sits in the task dir, each fs-stated. Missing expected files are rows too
 * (`exists: false`) — that absence is exactly what the model should see.
 * Never throws (an unreadable dir yields no rows) and never exceeds 24 rows. */
function readDp2ArtifactStatus(taskDir: string): Dp2ArtifactStatus[] {
	const expected = ["task.md", "output.md", "report.md", "trace.log", "worker.log"];
	const seen = new Set<string>();
	const rows: Dp2ArtifactStatus[] = [];
	const add = (rel: string): void => {
		if (rel === "" || seen.has(rel) || rows.length >= 24) return;
		seen.add(rel);
		const absolute = path.join(taskDir, rel);
		try {
			const stat = fs.statSync(absolute);
			if (!stat.isFile()) return;
			rows.push({ path: rel, exists: true, bytes: stat.size });
		} catch {
			rows.push({ path: rel, exists: false, bytes: 0 });
		}
	};
	for (const rel of expected) add(rel);
	let entries: string[] = [];
	try {
		entries = fs.readdirSync(taskDir).sort();
	} catch {
		entries = [];
	}
	for (const rel of entries) add(rel);
	return rows;
}

function splitPhaseProgress(phases: string): { done: number; total: number } {
	const match = /^(\d+)\/(\d+)$/.exec(phases.trim());
	if (!match) return { done: 0, total: 0 };
	return { done: Number(match[1]), total: Number(match[2]) };
}

/** The dp2 state's `task_type` is the dp1 3-value taxonomy; a role outside it
 * (vision / rag_chat / default) is reported as `coding` — the field is required
 * and dp2's question is about progress, not role. */
function dp2TaskType(headerType: string | undefined): string {
	return headerType === "research" || headerType === "review" ? headerType : "coding";
}

/** Wall budget mirror of `worker-mode.resolveBudgetMs` (that module imports this
 * one, so it cannot be imported back here): task.md `timeout:` minutes >
 * PI_WORKER_TIMEOUT_MS > 60m default. */
function dp2BudgetMin(timeoutHeader: string | undefined, env: NodeJS.ProcessEnv): number {
	const header = Number(timeoutHeader);
	if (timeoutHeader !== undefined && Number.isFinite(header) && header > 0) return header;
	const envMs = Number(env.PI_WORKER_TIMEOUT_MS);
	if (Number.isFinite(envMs) && envMs > 0) return Math.round(envMs / 60_000);
	return 60;
}

/** task.md header view dp2 needs: `phase:`, `type:` and `timeout:`. Undefined
 * when task.md is unreadable (the caller then keeps its original alert). */
export function readDp2TaskHeader(
	taskDir: string,
	env: NodeJS.ProcessEnv = process.env,
): { phase: string; taskType: string; budgetMin: number } | undefined {
	let content: string;
	try {
		content = fs.readFileSync(path.join(taskDir, "task.md"), "utf8");
	} catch {
		return undefined;
	}
	const phase = readTaskHeaderScalar(content, "phase") ?? "";
	return {
		phase: phase === "" ? "unknown" : phase,
		taskType: dp2TaskType(readTaskType(content).type),
		budgetMin: dp2BudgetMin(readTaskHeaderScalar(content, "timeout"), env),
	};
}

/** Normalised dp2 outcome. `action` is the closed vocabulary the caller branches
 * on: only `narrow` can ever be `acted` (D-011); `split`, `direct` and
 * `escalate` all fall through to the human alert. */
export interface Dp2CheckpointDecision {
	decisionId: string;
	triggerId: string;
	/** Raw `checkpoint_action` value when the service produced one. */
	answer?: string;
	action: "narrow" | "split" | "direct" | "escalate" | "none";
	available: boolean;
	acted: boolean;
	/** Effective mode as reported by the child (`payload.mode`, D-036: mode is an
	 * authorization OUTPUT). Absent when Python never answered; never read from
	 * the local `.mw/decide-points.json` mirror. */
	mode?: "auto" | "suggest";
	reason?: string;
	confidence?: number | null;
	confidenceSource?: string;
	budgetMin: number;
	elapsedMin: number;
}

export interface Dp2CheckpointInput {
	/** Project root that owns `.mw/` (the control workspace in dual-root runs). */
	projectDir: string;
	ownerKey: string;
	taskKey: string;
	taskDir: string;
	checkpoint: CheckpointInfo;
	/** Test seam: replaces the `mw decide run` child (production: runDecideMw). */
	run?: DecideRunner;
	/** Budget env override (tests); defaults to `process.env`. */
	env?: NodeJS.ProcessEnv;
}

function parseDecisionPayload(stdout: string): Record<string, unknown> | undefined {
	const trimmed = stdout.trim();
	const attempts = [trimmed];
	const lastLine = trimmed.split("\n").at(-1);
	if (lastLine !== undefined && lastLine !== trimmed) attempts.push(lastLine.trim());
	for (const text of attempts) {
		if (!text) continue;
		try {
			const parsed = recordOf(JSON.parse(text) as unknown);
			if (parsed) return parsed;
		} catch {
			// try the next candidate
		}
	}
	return undefined;
}

/** Ask dp2 for one checkpoint. NEVER throws and NEVER acts — it only decides
 * whether a `narrow` answer may replace the PM alert. `undefined` means the
 * feature is off for this project (design D-007 complete bypass: no spawn, no
 * write). */
export function decideDp2Checkpoint(input: Dp2CheckpointInput): Dp2CheckpointDecision | undefined {
	const policy = readDecidePolicy(input.projectDir);
	if (!policy.enabled) return undefined;
	// AC-016: the effective per-dp policy (row > decide.json > built-in) drives
	// the child budget and the confidence gate below. Resolution never throws.
	const effective = resolveDecidePolicy(DP2_CHECKPOINT_ID, input.projectDir);
	// Zero-spawn short-circuit ONLY (D-036): `readDp2Authorization` is a mirror of
	// the Python row parser, so its verdict is a cost saving, never an
	// authorization. `decision_points.decide_for` decides; a divergence resolves
	// to Python. That is also why the decision's `mode`/`acted` below are taken
	// from the child payload and not from this read.
	const authorization = readDp2Authorization(input.projectDir);
	if (!authorization.enabled) return undefined;

	const trend = readCheckpointTrend(input.taskDir);
	const triggerId = `${input.taskKey}#ckpt${trend.total}`;
	const base: Dp2CheckpointDecision = {
		decisionId: `${DP2_CHECKPOINT_ID}:${triggerId}`,
		triggerId,
		action: "none",
		available: false,
		acted: false,
		budgetMin: 0,
		elapsedMin: Math.max(0, Math.round(input.checkpoint.elapsedS / 60)),
	};

	const header = readDp2TaskHeader(input.taskDir, input.env ?? process.env);
	if (!header) return { ...base, reason: "input-incomplete" };
	base.budgetMin = header.budgetMin;
	const state = buildDp2CheckpointState({
		ownerKey: input.ownerKey,
		taskKey: input.taskKey,
		phase: header.phase,
		taskType: header.taskType,
		budgetMin: header.budgetMin,
		checkpoint: input.checkpoint,
		trend: trend.points,
		artifacts: readDp2ArtifactStatus(input.taskDir),
	});

	const run = input.run ?? runDecideMw;
	let raw: RawDecideRun;
	try {
		raw = run({
			projectDir: input.projectDir,
			dp: DP2_CHECKPOINT_ID,
			timeoutMs: Math.round(effective.timeoutS * 1000),
			// Structured envelope only: the registry is the question authority
			// (D-027), so no `questions` map rides along.
			input: JSON.stringify({ state }),
		});
	} catch {
		return { ...base, reason: "upstream-error" };
	}
	if (raw.timedOut) return { ...base, reason: "timeout" };
	if (raw.error !== undefined || raw.status !== 0) return { ...base, reason: "upstream-error" };
	const payload = parseDecisionPayload(raw.stdout);
	if (!payload) return { ...base, reason: "bad-response" };
	if (payload.available !== true) {
		const reason = typeof payload.reason === "string" && payload.reason !== "" ? payload.reason : "unavailable";
		return { ...base, reason };
	}

	const answer = recordOf(recordOf(payload.answers)?.[DP2_CHECKPOINT_QUESTION]);
	const value = typeof answer?.value === "string" ? answer.value.trim() : "";
	const confidence =
		typeof answer?.confidence === "number" && Number.isFinite(answer.confidence) ? answer.confidence : null;
	// D-036: the effective mode is the child's verdict. An absent/unknown value
	// stays undefined, which fails closed (`acted=false`) instead of guessing.
	const mode = payload.mode === "auto" || payload.mode === "suggest" ? payload.mode : undefined;
	const decision: Dp2CheckpointDecision = { ...base, available: true, confidence };
	if (mode !== undefined) decision.mode = mode;
	if (typeof payload.confidence_source === "string" && payload.confidence_source !== "") {
		decision.confidenceSource = payload.confidence_source;
	}
	if (value !== "") decision.answer = value;
	// Closed mapping: an unknown / missing value stays `none` (fail-closed onto
	// the human alert) — there is deliberately no default action branch.
	if (value === "narrow") decision.action = "narrow";
	else if (value === "split") decision.action = "split";
	else if (value === "direct-exec" || value === "direct") decision.action = "direct";
	else if (value === "escalate") decision.action = "escalate";
	// D-011/D-041: `narrow` is the ONLY action the machine may execute, and only
	// in the mode Python reports (`payload.mode`, not the local mirror). `suggest`
	// records the answer (Python already appended its evidence row) and still
	// wakes the PM (AC-015). AC-016: the confidence gate is the effective
	// per-dp `min_confidence` (Python applies the same threshold before it can
	// report `auto`); a payload without a usable confidence keeps the pre-AC-016
	// verdict and is never invented into one.
	const confident = confidence === null || confidence >= effective.minConfidence;
	decision.acted = mode === "auto" && decision.action === "narrow" && confident;
	return decision;
}

/** Write `<taskDir>/steer-dp2.md` (design §5.3). The PM process is the single
 * writer; the worker consumes the file at its next checkpoint tick and renames
 * it away. Returns false when the request could not be written — the caller
 * must then fall back to the human alert: a narrow that never reaches the
 * worker is not an acted decision. */
export function writeDp2SteerRequest(input: {
	taskDir: string;
	decision: Dp2CheckpointDecision;
	risk: string;
}): boolean {
	const target = path.join(input.taskDir, DP2_STEER_FILE);
	const remainingMin = Math.max(0, input.decision.budgetMin - input.decision.elapsedMin);
	const content = [
		`${DP2_STEER_REQUEST_HEADER} decision_id=${input.decision.decisionId} dp=${DP2_CHECKPOINT_ID}` +
			` risk=${input.risk} elapsed_minutes=${input.decision.elapsedMin}` +
			` budget_minutes=${input.decision.budgetMin} remaining_min=${remainingMin}`,
		`${DP2_NARROW_MARKER} dp2 已自动判定收窄本任务（decision_id=${input.decision.decisionId}）：` +
			`停止展开新工作，只保留能直接收敛的路径，优先保证已完成部分可交付；不新增文件、不改验收目标。` +
			`预算剩余约 ${remainingMin}m。`,
		"",
	].join("\n");
	// Atomic request: a half-written steer must never be consumed by the worker.
	const tmp = `${target}.tmp`;
	try {
		fs.writeFileSync(tmp, content, "utf8");
		fs.renameSync(tmp, target);
		return true;
	} catch {
		try {
			fs.rmSync(tmp, { force: true });
		} catch {
			// Best-effort cleanup only — the false return already selects the alert path.
		}
		return false;
	}
}

/** One `[DECISION] dp2 acted=1 decision_id=… trigger=…` correlation line in the
 * task's own trace (T-04d, design D-041 row 5).
 *
 * Written ONLY after the narrow actually executed — i.e. after
 * {@link writeDp2SteerRequest} returned true and the human alert was skipped. A
 * fallback to the alert (task not running / unwritable steer), `suggest` mode
 * and a disabled dp2 never write it: an un-executed decision may not claim
 * `acted=1`. Best-effort — a trace failure must never undo a written steer.
 */
export function appendDp2ActedTrace(taskDir: string, decision: Dp2CheckpointDecision): void {
	try {
		fs.appendFileSync(
			path.join(taskDir, "trace.log"),
			`[DECISION] dp2 acted=1 decision_id=${decision.decisionId} trigger=${decision.triggerId}\n`,
			"utf8",
		);
	} catch {
		// Diagnostic only: the steer file is the decision's contract.
	}
}

/** `running` / `settled` / `unknown` — the narrow branch may only replace the
 * human alert when the worker can still act on the steer (T-07b, DS-4). */
export type Dp2TaskLiveness = "running" | "settled" | "unknown";

function pidAlive(pid: number): boolean {
	try {
		process.kill(pid, 0);
		return true;
	} catch (err) {
		// EPERM: the process exists but is not ours — still alive. ESRCH: gone.
		return (err as NodeJS.ErrnoException).code === "EPERM";
	}
}

/** Is the worker this alert is about still able to consume a `steer-dp2.md`?
 *
 * The queue row is this loop's own view and is not evidence enough — it can lag
 * a run that already finished (the row is written by the launcher, the terminal
 * state by the worker itself, AC-022). So the worker's own product is consulted
 * first: `run.json` status, plus pid liveness for an `active` record (a worker
 * killed without a terminal write would otherwise look alive forever). Only
 * when the product gives no information does the ledger row decide.
 *
 * `unknown` (unreadable/unparsable record, no ledger evidence) is passed to the
 * caller as "not verified live" — the caller falls back to the human alert,
 * i.e. the fail-closed direction DS-4 requires. */
export function probeDp2TaskLiveness(taskDir: string, ledgerStatus?: string): Dp2TaskLiveness {
	try {
		const state = readRunState(taskDir);
		if (state !== undefined) {
			const kind = runStateKind(state);
			if (kind === "terminal") return "settled";
			if (kind === "active") {
				const pid = state.pid;
				if (typeof pid === "number" && Number.isInteger(pid) && pid > 0)
					return pidAlive(pid) ? "running" : "settled";
				return "running";
			}
		}
	} catch {
		// A probe that throws is not evidence of a live run: fail closed below.
		return "unknown";
	}
	if (ledgerStatus === "running" || ledgerStatus === "pending") return "running";
	if (
		ledgerStatus === "done" ||
		ledgerStatus === "failed" ||
		ledgerStatus === "needs-clarification" ||
		ledgerStatus === "lost"
	) {
		return "settled";
	}
	return "unknown";
}

/** Test seams + the explicit project root for the dp2 checkpoint hook.
 * Production passes only `projectDir`; `run` lets the suite replace the
 * `mw decide run` child (the triage-client DecideRunner seam). */
export interface Dp2CheckpointHooks {
	projectDir?: string;
	run?: DecideRunner;
}

export function startWorkerPollLoop(
	pi: ExtensionAPI,
	workerStore: WorkerStore,
	ackStore: AckStore,
	indexStore: IndexStore,
	agenticdocRoot: string,
	watch: PmWatchState,
	ui: PmUiHolder,
	pollIntervalMs = POLL_INTERVAL_MS,
	dp2Hooks?: Dp2CheckpointHooks,
): NodeJS.Timeout {
	// Baseline snapshot: rows already terminal when this window opens are
	// history — never replay their summaries. Only transitions observed while
	// this session is open are notified, at most once each.
	const notified = new Set(
		workerStore
			.readAll()
			.filter((e) => isTerminal(e.status))
			.map((e) => e.taskKey),
	);
	// AC-011/AC-012: subset of `notified` actually delivered this session. Feeds the
	// unread counter only (see the module note above) — never a suppression.
	const readbackDelivered = new Set<string>();
	// Running workers already escalated for divergence (AC-004): one PM wake
	// per task, at the first mid/high convergence checkpoint.
	const escalated = new Set<string>();
	// AC-006 (design §3.4/D7): consecutive model-error terminals per owned key,
	// process-local for this PM window's lifetime. Keyed by the owning project key
	// (not the task key) because the loop the alarm must expose spans DIFFERENT
	// task keys of the same key; any non-model-error terminal clears the streak.
	const modelErrorStreaks = new Map<string, number>();
	let widgetShown = false;
	// Pending-gate reminder delivery (AC-005/AC-018; design D-005/D-006/D-010).
	// The conductor (Python) is the sole decider and writer; this loop is the
	// only channel that wakes an idle PM (deliverPmAlert → triggerTurn). The same
	// ledger row must never wake the PM twice:
	//   - `reminderWatermark` = highest delivered ledger `seq`, persisted per
	//     session as a pi entry: a restart/resume continues where it left off and
	//     an append-only ledger row can never be re-delivered;
	//   - `unsequencedSeen` is the process-local fallback for a row missing `seq`
	//     (the conductor always sets it, so this is belt-and-braces only).
	// The watermark starts at the ledger's high-water mark at window open, so a
	// fresh window does not replay reminders that predate it (mirrors the
	// `notified` worker baseline). `reminderHistoryRead` gates the one-shot
	// resume path: when this session already recorded deliveries, the watermark
	// drops back to the last recorded seq so rows appended while the window was
	// down still reach the PM.
	const unsequencedSeen = new Set<string>();
	// AC-010: dropped reminders leave a visible record; dedup is process-local.
	const droppedRemindersSeen = new Set<string>();
	let reminderWatermark = 0;
	{
		const rows = readGateReminders(agenticdocRoot);
		for (const r of rows) if (r.seq > reminderWatermark) reminderWatermark = r.seq;
	}
	let reminderHistoryRead = false;
	// dp2 hook scope (T-07): `.mw/` lives at the control workspace root, one level
	// above the agenticdoc root in every layout (dual-root included).
	const dp2ProjectDir = dp2Hooks?.projectDir ?? path.dirname(agenticdocRoot);

	return setInterval(() => {
		try {
			const entries = workerStore.readAll();
			// AC-012/AC-013 unread counter input. `acked` is read only when the queue
			// actually holds terminal rows, so a queue with none adds no I/O. The
			// counter itself runs on the rows already read here (no second queue read).
			const acked = entries.some((e) => isTerminal(e.status)) ? new Set(ackStore.readAll().keys()) : undefined;
			// Live bottom widget for the watched key (per-window state, NOT the
			// shared _index.parallel active set — every window decides its own key).
			if (watch.key) {
				const lines = renderWatchLines(
					indexStore,
					workerStore,
					ackStore,
					agenticdocRoot,
					watch.key,
					watch.dispatchedTaskKeys,
				);
				// AC-012 (option B): an open-time terminal row is not replayed, but the
				// unread tail keeps it visible until acked.
				const unread = acked
					? countUnreadTerminal(
							entries.filter((e) => ownerKeyOf(e, agenticdocRoot) === watch.key),
							acked,
							readbackDelivered,
						)
					: 0;
				if (unread > 0) lines.push(`  ${unread} unread — terminal result(s) not delivered this session`);
				applyWatchWidget(ui, lines);
				widgetShown = true;
			} else {
				// AC-013: with no watched key the window renders at most ONE line — the
				// unread count over the whole queue — and never broadcasts a message.
				const unread = acked ? countUnreadTerminal(entries, acked, readbackDelivered) : 0;
				if (unread > 0) {
					applyWatchWidget(ui, [`[mw] no watched key | ${unread} unread terminal result(s)`]);
					widgetShown = true;
				} else if (widgetShown) {
					applyWatchWidget(ui, undefined);
					widgetShown = false;
				}
			}
			// Divergence escalation (AC-004): running workers past the convergence
			// checkpoint whose machine risk is mid/high wake the PM once per task
			// with the evidence — the PM (fullest context) decides continue /
			// descope / kill + split / takeover. Low-risk checkpoints stay in the
			// widget only; no cross-window broadcast (scoped to the watched key ∪
			// this window's dispatched tasks — mw-crosskey-risk-escalation D-101).
			for (const entry of entries) {
				if (entry.status !== "running" || escalated.has(entry.taskKey)) continue;
				// Ownership is "watched key OR dispatched by this window": a task this
				// window sent across keys (explicit `key:` dispatch, gate fallback to
				// _scratch) is still this PM's work, while other windows' workers stay
				// silent. `!watch.key` stays first: a window watching nothing must not
				// start delivering off historical dispatch records.
				const ownerKey = ownerKeyOf(entry, agenticdocRoot);
				const owned = watch.dispatchedTaskKeys?.has(entry.taskKey) ?? false;
				if (!watch.key || (ownerKey !== watch.key && !owned)) continue;
				const ck = readTaskProgress(path.dirname(entry.taskPath))?.checkpoint;
				if (!ck || ck.risk === "low") continue;
				escalated.add(entry.taskKey);
				const taskDir = path.dirname(entry.taskPath);
				// dp2 (T-07 / design D-011): a machine answer may replace this wake with
				// the ONE reversible action, `narrow`. `escalated.add` above already booked
				// the once-per-task bound, so BOTH branches stay at one wake/steer per task
				// per PM session (design §5.4 invariant 3). Closed states (no
				// `.mw/decide.json`, dp2 disabled, suggest mode) return undefined and fall
				// through to the byte-identical alert below.
				const dp2 = decideDp2Checkpoint({
					projectDir: dp2ProjectDir,
					ownerKey,
					taskKey: entry.taskKey,
					taskDir,
					checkpoint: ck,
					run: dp2Hooks?.run,
				});
				let dp2Fallback = false;
				if (dp2?.acted) {
					// T-07b (DS-4 fallback): a `narrow` may only replace the human wake when
					// the worker can still consume `steer-dp2.md`. A settled/terminal run (or a
					// probe that yields no live evidence) gets the UNCHANGED alert plus an
					// explicit fallback line instead — writing a steer nobody reads would be
					// the exact fail-open DS-4 forbids.
					const liveness = probeDp2TaskLiveness(taskDir, entry.status);
					if (liveness !== "running") {
						dp2Fallback = true;
					} else if (writeDp2SteerRequest({ taskDir, decision: dp2, risk: ck.risk })) {
						// T-04d: the narrow really executed (steer landed, alert skipped) —
						// record the acted decision in the task trace before reporting it.
						appendDp2ActedTrace(taskDir, dp2);
						// No triggerTurn: the decision already happened, the worker picks the steer
						// up at its next checkpoint tick, and the PM must not spend an agent turn
						// on it (design §5.3 / AC-004). The transcript still records it.
						displaySummary(
							pi,
							`[mw] dp2 已自动收窄 ${entry.taskKey}（decision_id=${dp2.decisionId}，risk=${ck.risk}）；` +
								`worker 将在下一个检查点 tick 注入收窄 steer。如需改判：手动处置或 mw decide dp off ${DP2_CHECKPOINT_ID}。`,
						);
						continue;
					}
					// A failed steer write keeps the pre-dp2 alert byte-identical (the worker may
					// still be alive; the file was simply unwritable) — only "not running"
					// carries the fallback line.
				}
				// split / direct-exec / escalate / mode=suggest / every degraded path: the
				// pre-dp2 alert below stays byte-identical and still triggers a turn.
				// Cross-key alerts carry the owner key right after the worker name
				// (D-102) so the PM can tell an off-watch task from a watched-key one;
				// the watched-key label keeps the byte-exact `'name' ` form (AC-004).
				const workerLabel =
					ownerKey === watch.key ? `'${entry.taskKey}' ` : `'${entry.taskKey}'（owner key=${ownerKey}）`;
				deliverPmAlert(
					pi,
					`[mw] 发散风险：worker ${workerLabel}检查点 risk=${ck.risk}` +
						`（elapsed ${Math.round(ck.elapsedS / 60)}m，reads=${ck.reads} writes=${ck.writes}，phases=${ck.phases}，` +
						`重复读 top=${ck.repeatTop}）。机器判据仅供参考——请结合本 key 最全上下文判断：继续等待 / steer 收窄范围 / 终止并分拆重派 / PM 直执。` +
						`证据：${path.join(taskDir, "trace.log")}（[CHECKPOINT] 行）与 ${path.join(taskDir, "progress.md")}（自评行；无写工具角色另含框架机器行）。` +
						(dp2Fallback ? `\n${DP2_NARROW_FALLBACK_LINE}` : ""),
				);
			}
			for (const entry of entries) {
				if (notified.has(entry.taskKey) || !isTerminal(entry.status)) continue;
				// C3 — no watched key: stay silent (no cross-window broadcast), but
				// consume the terminal transition for this session so adopting a key
				// later cannot resurrect it (locked by "stays silent without a watched
				// key and for tasks under other keys"). NOT counted as delivered: the
				// AC-013 unread counter must still surface it.
				if (!watch.key) {
					notified.add(entry.taskKey);
					continue;
				}
				// C1 — another key's terminal row: not this window's business AND not
				// consumed, so the owner window (or this window after a key takeover)
				// still gets its one readback. No I/O on this path (R5).
				if (ownerKeyOf(entry, agenticdocRoot) !== watch.key) continue;
				// Owned + watched: account the delivery exactly once. This stays before
				// `recordWriteScopeResidualRisks` below — `notified` is also the
				// per-task-per-session bound for that alarm (`recordDispatchAlarm` has no
				// dedup of its own).
				notified.add(entry.taskKey);
				readbackDelivered.add(entry.taskKey);
				// Task dir from the queue row taskPath: works for keyed {key}/workers/<task-key>/ and legacy root paths.
				const taskDir = path.dirname(entry.taskPath);
				// AC-007/DD-08 residual risk: a contract-allowed write whose basename
				// still names a deny-list artifact is only observable here (the guard
				// wrote `blocked=false risk=deny-basename` and moved on). Reuses the
				// single dispatch-alarm ledger channel; `notified` above bounds it to
				// once per task per session.
				recordWriteScopeResidualRisks(agenticdocRoot, entry.taskKey, taskDir);
				// AC-006/design §3.4 (D7): model-error perception for this terminal
				// transition. Same `notified` dedup as the line above — one evaluation
				// per task per session — and deliberately perception only: it records a
				// ledger alarm and never touches the re-dispatch decision.
				recordModelErrorTerminal(
					agenticdocRoot,
					ownerKeyOf(entry, agenticdocRoot),
					entry.taskKey,
					taskDir,
					modelErrorStreaks,
				);
				// T-08 (spec §6.2 / design D-013): settle the decision this task
				// executes. Same once-per-terminal-transition bound as the two cells
				// above (`notified`, which also arms the per-session dedup) and
				// idempotent on (decision_id, outcome, run_id), so a PM restart replay
				// writes nothing. A task without a `decision:` head line stays
				// un-associated — the 5 un-associable classes of spec §6.2 are never
				// guessed at.
				const settled = recordDecisionSettle(agenticdocRoot, ownerKeyOf(entry, agenticdocRoot), entry, taskDir);
				// An archive write failure is the one settle outcome that must be loud
				// (D2-S0: the archive is a correctness dependency): the decision stays
				// without its result correlation and the PM says so in the transcript.
				for (const skip of settled.skipped) {
					if (skip.reason !== "append-failed") continue;
					displaySummary(
						pi,
						`[mw] decision settle 写入失败：${skip.decisionId || entry.taskKey} 的档案行未追加（decisions.jsonl 不可写），关联结果未落地。`,
					);
				}
				// Terminal readback (AC-014): inject the full output.md body into
				// the conversation so worker results reach the PM without manual
				// file reads. Falls through to the spawn-failure / no-output
				// notices when there is nothing to read back. Sent via
				// deliverWorkerResult (triggerTurn) so an idle PM wakes up,
				// processes the result, and runs the next step — the finish call
				// of dispatch → monitor → finish call → pm run (AC-015).
				const header = `[${entry.taskKey}] ${entry.status}${heartbeatStatsSuffix(taskDir, entry)}`;
				const body = readOutputBody(taskDir);
				if (body) {
					deliverWorkerResult(pi, `${header}:\n\n${body}\n\n${PM_CONTINUE_HINT}`);
				} else {
					// Terminal but no output.md summary — never stay silent. Prefer the
					// launcher's exact spawn-failure reason (e.g. missing credential) over
					// the generic crash/timeout guess; both point at the per-task log.
					const logPath = path.join(taskDir, "worker.log");
					const spawnFailure = readSpawnFailure(taskDir);
					deliverWorkerResult(
						pi,
						`${header} — ${
							spawnFailure
								? `${spawnFailure}。日志：${logPath}`
								: `无 output.md 摘要（worker 可能崩溃/超时）。日志：${logPath}`
						}\n\n${PM_CONTINUE_HINT}`,
					);
				}
			}

			// Pending-gate reminders (appended last: the worker terminal-readback
			// order above must not change). Read-only — the ledger belongs to the
			// conductor; this branch never writes it.
			const reminders = readGateReminders(agenticdocRoot);
			if (!reminderHistoryRead) {
				reminderHistoryRead = true;
				let delivered = 0;
				try {
					for (const e of ui.ctx?.sessionManager.getEntries() ?? []) {
						if (e.type !== "custom" || e.customType !== GATE_REMINDER_ENTRY_TYPE) continue;
						const data = e.data as { seq?: unknown } | undefined;
						if (typeof data?.seq === "number" && data.seq > delivered) delivered = data.seq;
					}
				} catch {
					// Session entries unavailable — treat this as a fresh window.
				}
				// Resume from the recorded point (may be below the open-time baseline,
				// so rows appended while this window was down are still delivered);
				// a fresh session keeps the no-replay baseline.
				if (delivered > 0) reminderWatermark = delivered;
			}
			for (const reminder of reminders) {
				// Multi-window scope (D-010): a keyed gate is only this window's
				// business when it watches that key; keyless/stage-level gates fall
				// through to the per-session watermark. A window watching nothing
				// stays silent, like the worker summaries above — but AC-010 forbids
				// a SILENT drop, so each discard is recorded first.
				if (!watch.key) {
					recordDroppedGateReminder(pi, droppedRemindersSeen, reminder, "no-watch");
					continue;
				}
				if (reminder.gateKey !== "" && reminder.gateKey !== watch.key) {
					recordDroppedGateReminder(pi, droppedRemindersSeen, reminder, "other-key");
					continue;
				}
				const dedup = `${reminder.gateId}:${reminder.reminderN}`;
				if (reminder.seq > 0) {
					// Session watermark: the row was delivered already (this tick or a
					// previous session) whenever its seq is not ahead of the mark.
					if (reminder.seq <= reminderWatermark) continue;
					reminderWatermark = reminder.seq;
				} else {
					if (unsequencedSeen.has(dedup)) continue;
					unsequencedSeen.add(dedup);
				}
				// Persist the delivery so /new, /resume and restarts do not replay it.
				pi.appendEntry(GATE_REMINDER_ENTRY_TYPE, {
					seq: reminder.seq,
					gateId: reminder.gateId,
					n: reminder.reminderN,
				});
				const scope = reminder.gateKey === "" ? "stage" : `key=${reminder.gateKey}`;
				deliverPmAlert(
					pi,
					`[mw] 门提醒（${reminder.reminderN}）：gate ${reminder.gateId}（kind=${reminder.gateKind}，${scope}）已 pending 超阈，等待人工应答。` +
						`（判定由 conductor 完成；用 /autopilot gates 查看，/autopilot gate ${reminder.gateId} approve|reject 应答。）` +
						(reminder.detail ? ` ${reminder.detail}` : ""),
				);
			}
		} catch (err) {
			// Transient I/O error (e.g. EACCES during concurrent rename) — skip this
			// tick, but AC-010 forbids a silent drop: leave one visible read-error
			// record (deduplicated, no `seq`, so it cannot advance the watermark).
			recordDroppedGateReminder(
				pi,
				droppedRemindersSeen,
				{ gateId: "-", reminderN: 0, gateKey: "" },
				"read-error",
				err instanceof Error ? err.message : String(err),
			);
		}
	}, pollIntervalMs);
}

/** Marker opening the injected parallel-protocol block, and the idempotency
 * guard: a handler that already sees it in the chained system prompt must not
 * append it a second time (two loaded bundle copies would otherwise duplicate
 * the text on every run). */
export const PARALLEL_PROTOCOL_MARKER = "[mw] 并行优先协议";

/** Static parallel-first rules appended to the PM window's system prompt once
 * per agent run (mw-parallel-protocol). Static on purpose: a constant suffix
 * keeps the system-prompt prefix cacheable, and `before_agent_start` costs no
 * session tokens (an injected message would accumulate one per run). The two
 * conflict surfaces are deliberately different: research/review workers are
 * read-only (worker-mode.ts TOOL_ALLOWLISTS), so research batches in the
 * spec/design phases parallelize freely and only need a unique note file per
 * research question; coding workers share files and must be split by
 * file/module boundary. PM-only by construction: pmActivate() runs only when
 * PI_WORKER_TASK is unset (index.ts). */
export const PARALLEL_PROTOCOL = [
	`${PARALLEL_PROTOCOL_MARKER}（PM 常驻规则）：`,
	"1. 拆解任何 phase（spec/design/plan/tasks）之前，先做并行性分析：可并行单元 / 共享资源与文件冲突面 / 必须串行的理由。",
	"2. spec/design 的调研与证据收集默认全并行：把调研拆成互不重叠的研究问题 RQ-1..N，一次性派发 N 个 type: research worker",
	"   （只读角色，彼此无文件冲突），每个 RQ 只写唯一的 evidence/research/<phase>-<rq-slug>-<date>.md；禁止两个 worker 写同一文件。",
	"3. 编码按文件/模块边界并行：同一文件同一时刻只允许一个 worker。",
	"4. 相位文档（spec.md / design.md）由 PM 自己串行写，不派 worker。",
	"5. 派发前先看 widget 上的 running worker 数：能并行就不要串行等待；worker 终态回读后立刻补派下一批。",
	"6. 引用图片/截图/mockup 的任务用 type: vision 派发（视觉角色，worker 读取图片文件并受 image 能力门禁约束）。",
].join("\n");

export function pmActivate(pi: ExtensionAPI): void {
	const projectDir = process.cwd();
	const agenticdocRoot = resolveAgenticdocRoot(projectDir);
	const workerStore = new WorkerStore(agenticdocRoot);
	const ackStore = new AckStore(agenticdocRoot);
	const indexStore = new IndexStore(agenticdocRoot);

	// Per-window watch state: the key THIS window explicitly executes (set via
	// /mw-watch or /pm-key switch|new). Worker summaries and the bottom progress
	// widget are scoped to it — replacing the old global active-keys matching
	// that made every window notify about every active key.
	const watch: PmWatchState = { key: undefined };
	const ui: PmUiHolder = { ctx: undefined };
	const refreshWatch = (ctx: ExtensionContext): void => {
		if (!watch.key) {
			setWatchWidget(ctx, undefined);
			return;
		}
		setWatchWidget(
			ctx,
			renderWatchLines(indexStore, workerStore, ackStore, agenticdocRoot, watch.key, watch.dispatchedTaskKeys),
		);
	};

	// Register commands and tools during loading (safe — not action methods)
	registerPmKeyCommands(pi, indexStore, watch, refreshWatch, agenticdocRoot);
	registerPmSaveCommand(pi, indexStore, workerStore, watch, agenticdocRoot);
	registerMwCommands(pi, projectDir, workerStore, ackStore, watch, agenticdocRoot);
	registerMwTools(pi, projectDir);
	registerAdvancePhaseTool(pi, projectDir, indexStore);
	registerWorkerTools(pi, workerStore, ackStore, indexStore, agenticdocRoot, watch, projectDir);
	registerSwitchKeyTool(pi, indexStore, watch, refreshWatch, agenticdocRoot);
	registerWorkerCommands(pi, workerStore, indexStore, agenticdocRoot, watch, projectDir);
	// RAG tool surface (D-002): registration is structural — an empty enabled
	// set registers nothing and probes nothing. A broken config must not take
	// the whole PM window down (dispatch is gated separately in ui-bridge).
	try {
		registerRagTools(pi, projectDir);
	} catch (err) {
		console.error(`[mw] rag tools disabled: ${err instanceof Error ? err.message : String(err)}`);
	}
	// run-detached surface (D-005): registered in BOTH activate paths (the
	// registerRagTools precedent) so PM and worker windows can dispatch
	// background commands; the worker allowlist gate decides visibility.
	try {
		registerRunDetachedTool(pi, projectDir);
	} catch (err) {
		console.error(`[mw] run-detached disabled: ${err instanceof Error ? err.message : String(err)}`);
	}
	registerWatchCommand(pi, watch, refreshWatch, indexStore);
	// Autopilot console (T-15): /autopilot status|gates|gate|timeline|enable|
	// disable|pause|resume|roadmap — stateless, file-derived (D-005).
	registerAutopilotCommands(pi, projectDir);
	// Dispatch model chain, main-window side (mw-dispatch-models): record this
	// window's model for worker inheritance and apply a configured `main` role.
	registerMainWindowModel(pi);

	// Hard gate: pm-state.md's '- Phase:' / '- Claim-Id:' interface lines are
	// script-owned (advance_phase.py / update_index.py). Hand-editing them is
	// how phase gates get bypassed (mw-worker-timeout-convergence: pm-state
	// hand-set to EXECUTE while _index.parallel stayed at SPEC), so the edit is
	// blocked at the tool layer and the agent is pointed at the script.
	registerPmStateGuard(pi, projectDir, agenticdocRoot);

	// Parallel-first protocol (mw-parallel-protocol): append the constant block
	// to this run's system prompt. Appending (never replacing) preserves what
	// other extensions chained in before us.
	pi.on("before_agent_start", (event) => {
		const base = typeof event.systemPrompt === "string" ? event.systemPrompt : "";
		if (base.includes(PARALLEL_PROTOCOL_MARKER)) return undefined;
		return { systemPrompt: base === "" ? PARALLEL_PROTOCOL : `${base}\n\n${PARALLEL_PROTOCOL}` };
	});

	// Start worker status poll loop (setInterval is safe; displaySummary inside fires later)
	const pollHandle = startWorkerPollLoop(
		pi,
		workerStore,
		ackStore,
		indexStore,
		agenticdocRoot,
		watch,
		ui,
		POLL_INTERVAL_MS,
		{
			projectDir,
		},
	);
	// Session teardown stops the loop (review m3): a fresh runtime re-runs
	// pmActivate and starts a new one, so this only removes the zombie that
	// would keep ticking against a disposed context after /reload or session
	// replacement. It also stops the autopilot monitor panel (AC-018/VC-023):
	// the next session_start re-arms it via autoStartMonitor, so the panel is
	// never left pointing at a disposed ctx (and no interval leaks). stopMonitor
	// is a no-op when no panel is active — it never clears non-active state.
	pi.on("session_shutdown", () => {
		clearInterval(pollHandle);
		stopMonitor();
	});

	// After each agent turn, scan for new task.md files and dispatch them (AC-030).
	// Undocumented keys are skipped and reported once per session (docs gate).
	// Gate broadcast is scoped to this window's watched key (AC-011). The SCAN
	// is global and read-only (T-19): the write right covers this window's key,
	// `_scratch`, and ORPHANED keys (claim-free repair).
	const docGateWarned = new Set<string>();
	// Dispatch alarms are once per kind per session for the REFUSAL kinds: a
	// queue that stays broken must not append a ledger row or wake the PM on
	// every settled turn. `orphaned-keys` is deduped per KEY inside the scan
	// (`orphanedWarned`), so a newly orphaned key is still reported immediately
	// while a key that stays orphaned is not re-reported every turn.
	const dispatchAlarmsSeen = new Set<DispatchAlarmKind>();
	const orphanedWarned = new Set<string>();
	// T-22: `out-of-scope` notice dedup is per KEY (not per kind): a key left
	// unregistered with undispatched work must be reported once per session, not
	// on every settled turn, while a DIFFERENT key can still surface later.
	const unregisteredWarned = new Set<string>();
	pi.on("agent_settled", () => {
		dispatchNewTasks(workerStore, agenticdocRoot, {
			warnedKeys: docGateWarned,
			onDocGate: makeScopedDocGateNotifier(pi, watch),
			scope: "pm",
			watchedKey: watch.key,
			orphanedWarned,
			// Per-task write-face refusals are recorded by the scan itself (one
			// ledger row each, never deduped); this only delivers the human alert.
			onRefusal: (text) => deliverPmAlert(pi, text),
			unregisteredWarned,
			// AC-022 (T-20): the product decides. A candidate whose own run.json
			// already ended (or is still live) is refused before any queue write;
			// `supersedes:` in task.md is the only way to replace a finished run, and
			// the replaced directory is never touched. Every read is best-effort
			// ("no information" ⇒ pre-T-20 behaviour, zero backfill).
			runVerdict: (task) =>
				evaluateRunIdentity({
					taskDir: task.taskDir,
					readTaskContent: task.readTaskContent,
					resolveTaskDir: (key) => {
						const dir = path.join(path.dirname(task.taskDir), key);
						return fs.existsSync(dir) ? dir : undefined;
					},
				}),
			onAlarm: (alarm) => {
				// The per-kind gate is for refusals only; a notice (`orphaned-keys`)
				// is already deduped per key by the scan and must still reach the PM
				// when a DIFFERENT key becomes orphaned later in the session.
				if (!isNoticeDispatchAlarm(alarm.kind)) {
					if (dispatchAlarmsSeen.has(alarm.kind)) return;
					dispatchAlarmsSeen.add(alarm.kind);
				}
				recordDispatchAlarm(agenticdocRoot, alarm);
				deliverPmAlert(pi, formatDispatchAlarm(alarm));
			},
		}).catch(() => {
			// Dispatch errors are non-fatal — PM loop continues
		});
	});

	// Spec-write auto-takeover: tool_execution_end carries no args, so correlate
	// them with the args captured on tool_execution_start via toolCallId. Only
	// write/edit calls are tracked; the map entry is consumed on end.
	const pendingToolArgs = new Map<string, { toolName: string; args: unknown }>();
	pi.on("tool_execution_start", (event) => {
		if (event.toolName === "write" || event.toolName === "edit") {
			pendingToolArgs.set(event.toolCallId, { toolName: event.toolName, args: event.args });
		}
	});
	// Evidence-review notices fire once per (key, phase) per session.
	const evidenceReviewNotified = new Set<string>();
	pi.on("tool_execution_end", (event, ctx) => {
		const pending = pendingToolArgs.get(event.toolCallId);
		pendingToolArgs.delete(event.toolCallId);
		if (!pending || event.isError) return;
		const target = docWriteTarget(pending.toolName, pending.args, projectDir, agenticdocRoot);
		if (target) {
			autoTakeOverFromDoc(pi, indexStore, watch, refreshWatch, target.key, target.doc, agenticdocRoot, ctx).catch(
				() => {
					// Takeover failures (e.g. lock contention) must never disturb the turn
				},
			);
			// Phase-doc write with its evidence already present → notice that the
			// doc's claims can be re-reviewed against the notes (plan has no
			// evidence phase). A notice, never an injected instruction.
			if (target.doc !== "plan.md") {
				evidenceReviewNotice(
					ctx,
					target.key,
					target.doc === "spec.md" ? "spec" : "design",
					agenticdocRoot,
					evidenceReviewNotified,
				);
			}
			return;
		}
		// Research-note write: not a claim signal, but it may complete the
		// evidence set for an already-written phase doc → review notice.
		const ev = evidencePhaseFromWrite(pending.toolName, pending.args, projectDir, agenticdocRoot);
		if (ev) {
			evidenceReviewNotice(ctx, ev.key, ev.phase, agenticdocRoot, evidenceReviewNotified);
		}
	});

	// Defer action method calls to after runner.initialize() (session_start fires post-init)
	pi.on("session_start", async (_event, ctx) => {
		// Capture the UI context so the poll loop can render the bottom widget.
		ui.ctx = ctx;
		// Autopilot progress panel: auto-show for enabled projects so a stalled
		// key is visible without anyone running a command (mw-autopilot-stall-feedback
		// AC-008). An explicit /autopilot monitor off suppresses it for this session.
		autoStartMonitor(ctx, projectDir);
		// Resume the watched key this session had before restart/resume.
		await restoreWatch(pi, watch, indexStore, workerStore, ackStore, agenticdocRoot, ctx);
		// Auto-init project if it hasn't been initialized yet. Gate on .agenticdoc
		// (the project marker mw init creates), NOT on a project-local bundle copy:
		// the extension is now installed GLOBALLY (mw setup), so no project-local
		// bundle exists and checking for one would re-run init on every session.
		const initialized = fs.existsSync(path.join(projectDir, ".agenticdoc"));
		if (!initialized) {
			const result = initMw(projectDir);
			if (result.ok) {
				displaySummary(pi, "[mw] Project initialized — .agenticdoc/ .mw/ .pi/extensions/ created.");
			} else {
				displaySummary(pi, `[mw] Init failed: ${result.error}`);
				return;
			}
		}

		// Auto-start mw background service if not already running.
		// After spawning, poll for the PID file so the agent's first turn doesn't
		// race against Python startup and falsely report mw as not running.
		// Stability window: the PID must stay alive for 3s — mw serve can die
		// right after startup (route precheck failure) and the old check would
		// report a false "started" in that window (mw-dispatch-reliability AC-005).
		const mwStatus = getMwStatus(projectDir);
		if (!mwStatus.running) {
			const started = startMw(projectDir);
			if (started) {
				const confirmed = await waitForMwStart(projectDir, 8000);
				displaySummary(
					pi,
					confirmed
						? "[mw] Background service started."
						: "[mw] Background service 启动未确认（可能预检失败或仍在启动）——运行 /mw doctor 诊断。",
				);
			} else {
				displaySummary(pi, "[mw] Could not find mw.py — run `mw start --project=.` manually.");
			}
		} else {
			// Stale-serve detection: a serve started before the current mw code
			// silently misses features (e.g. conductor supervision) — surface it
			// instead of letting /autopilot enable promise a conductor that never
			// spawns.
			const stale = serveStaleness(projectDir);
			if (stale?.stale) {
				displaySummary(
					pi,
					`[mw] serve (PID ${mwStatus.pid}) is running stale code — ${stale.detail}. Run /mw restart.`,
				);
			}
		}

		// The project goal is the north-star every key/spec derives from.
		// Do NOT fabricate a placeholder — if it isn't established yet, softly
		// guide the user into the goal brainstorm workflow (/goal). An
		// established goal (or a legacy goal.md with content) is left untouched.
		// Headless sessions skip the goal nudge (see nudgeGoalUnestablished).
		nudgeGoalUnestablished(pi, agenticdocRoot, ctx.hasUI);
	});
}
